window.DQ=window.DQ||{};DQ["kashrut"]={"a":[["אֵיזוֹ בְּהֵמָה כְּשֵׁרָה לַאֲכִילָה?",["גָּמָל","חֲזִיר","פָּרָה"],2,"לַפָּרָה יֵשׁ שְׁנֵי הַסִּימָנִים: פַּרְסָה סְדוּקָה וּמַעֲלַת גֵּרָה. לַגָּמָל אֵין פַּרְסָה סְדוּקָה, וְהַחֲזִיר אֵינוֹ מַעֲלֶה גֵרָה.","פֶּרֶק י״ז, הֲלָכוֹת ג׳–ד׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["אֵיזֶה דָּג כָּשֵׁר?",["דָּג עִם קַשְׂקַשִּׂים","שְׁרִימְפְּס","דָּג חָלָק בְּלִי קַשְׂקַשִּׂים"],0,"סִימַן הַדָּג הַכָּשֵׁר הוּא סְנַפִּיר וְקַשְׂקֶשֶׂת. הַשְּׁרִימְפְּס אָסוּר, וְדָג בְּלִי קַשְׂקַשִּׂים – טָמֵא.","פֶּרֶק י״ז, הֲלָכוֹת א׳, ז׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["הַתֻּכִּי שֶׁל יוֹסִי בַּכְּלוּב, וְהַקְּעָרָה שֶׁלּוֹ רֵיקָה. אַבָּא קוֹרֵא לַאֲרוּחָה. מָה עוֹשֶׂה יוֹסִי קֹדֶם?",["רָץ מִיָּד לַשֻּׁלְחָן","מְמַלֵּא לַתֻּכִּי אֹכֶל","מְחַכֶּה עִם זֶה לְמָחָר"],1,"אָסוּר לֶאֱכֹל לִפְנֵי שֶׁנּוֹתְנִים אֹכֶל לְבַעֲלֵי הַחַיִּים שֶׁלָּנוּ. תֻּכִּי בַּכְּלוּב אֵינוֹ יָכוֹל לִמְצֹא אֹכֶל לְבַד, וְהוּא תָּלוּי רַק בָּנוּ.","פֶּרֶק ט״ו, הֲלָכָה ד׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["חֲמוֹר נָפַל בַּדֶּרֶךְ תַּחַת מַשָּׂא כָּבֵד. מָה עוֹשִׂים?",["עוֹבְרִים הָלְאָה","מוֹסִיפִים עָלָיו עוֹד שַׂק","עוֹזְרִים לְהוֹרִיד אֶת הַמַּשָּׂא"],2,"מִצְוָה מִן הַתּוֹרָה לַעֲזֹר לְהוֹרִיד מַשָּׂא מֵחֲמוֹר שֶׁנָּפַל – גַּם כְּדֵי לַעֲזֹר לַבְּעָלִים, וְגַם כְּדֵי לְהַצִּיל אֶת הַחֲמוֹר מִצַּעַר.","פֶּרֶק ט״ו, הֲלָכָה ב׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["בָּעֵץ יֵשׁ קֵן שֶׁל יוֹנַת בָּר, וְהָאֵם יוֹשֶׁבֶת עַל הַבֵּיצִים. אֵלִי צָרִיךְ אֶת הַבֵּיצִים. מָה הוּא עוֹשֶׂה קֹדֶם?",["מַבְרִיחַ אֶת הָאֵם בְּקוֹל","לוֹקֵחַ אֶת הָאֵם עִם הַבֵּיצִים","מַכְנִיס יָד מִתַּחַת לָאֵם"],0,"הַתּוֹרָה צִוְּתָה: \"שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם, וְאֶת הַבָּנִים תִּקַּח לָךְ\". מְשַׁלְּחִים בְּקוֹל אוֹ בְּמַכָּה קַלָּה עַל הַקֵּן, וְרַק אַחַר כָּךְ לוֹקְחִים.","פֶּרֶק ט״ז, הֲלָכוֹת א׳, ד׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["אֵיזֶה עוֹף מֻתָּר לֶאֱכֹל?",["נֶשֶׁר","תַּרְנְגוֹל הוֹדוּ","יַנְשׁוּף"],1,"הַנֶּשֶׁר וְהַיַּנְשׁוּף נִמְנִים בַּתּוֹרָה בֵּין הָעוֹפוֹת הַטְּמֵאִים. עַל תַּרְנְגוֹל הַהוֹדוּ הוֹרוּ הָרַבָּנִים שֶׁהוּא כָּשֵׁר, וְכָךְ נוֹהֲגִים כָּל יִשְׂרָאֵל.","פֶּרֶק י״ז, הֲלָכוֹת ה׳–ו׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["בְּמָה מְכַבְּדִים אֶת סְעוּדַת הַשַּׁבָּת?",["לֶחֶם יָבֵשׁ בִּלְבַד","אֹכֶל מָהִיר בַּעֲמִידָה","תַּבְשִׁיל בָּשָׂר טָעִים"],2,"מִצְוָה לְהִתְעַנֵּג בְּשַׁבָּת, וְרֹב הָאֲנָשִׁים מִתְעַנְּגִים בַּאֲכִילַת בָּשָׂר. לָכֵן מִצְוָה לֶאֱכֹל בָּשָׂר בְּשַׁבָּת וּבְיוֹם טוֹב.","פֶּרֶק י״ד, הֲלָכָה ג׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["חָתוּל רְחוֹב רָעֵב מְיַלֵּל לְיַד הַבַּיִת. מָה עוֹשֶׂה נֹעַם?",["שָׂם לוֹ שְׁיָרֵי אֹכֶל","מוֹשֵׁךְ לוֹ בַּזָּנָב","מְגָרֵשׁ אוֹתוֹ בְּמַקֵּל"],0,"אָסוּר לְצַעֵר בַּעֲלֵי חַיִּים. אֶת חַיּוֹת הַהֶפְקֵר אֵין חוֹבָה לְהַאֲכִיל, אֲבָל מִי שֶׁנּוֹתֵן לָהֶן מִשְּׁיָרֵי הָאֹכֶל – מְקַיֵּם מִצְוָה.","פֶּרֶק ט״ו, הֲלָכוֹת ו׳, ט״ו","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["הַיְּלָדִים רוֹצִים לְאַמֵּץ כֶּלֶב. מָה צָרִיךְ לִבְדֹּק קֹדֶם?",["שֶׁהוּא נוֹבֵחַ הֲכִי חָזָק","שֶׁיֵּשׁ מִי שֶׁיַּאֲכִיל וִינַקֶּה","שֶׁיֵּשׁ לוֹ פַּרְוָה יָפָה"],1,"אָמְרוּ חֲכָמִים: לֹא יַכְנִיס אָדָם בַּעַל חַיִּים לְבֵיתוֹ אִם אֵינוֹ יוֹדֵעַ שֶׁיּוּכַל לָתֵת לוֹ מָזוֹן כָּרָאוּי. צָרִיךְ גַּם מָקוֹם מַתְאִים וְנִקָּיוֹן.","פֶּרֶק ט״ו, הֲלָכוֹת ד׳, י״ג","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["שׁוֹר עוֹבֵד בְּדִישַׁת חִטִּים בַּגֹּרֶן. מָה הַדִּין?",["נוֹתְנִים לוֹ לֶאֱכֹל מֵהַחִטִּים","שָׂמִים לוֹ מַחְסוֹם עַל הַפֶּה","קוֹשְׁרִים אוֹתוֹ רָחוֹק מֵהָאֹכֶל"],0,"\"לֹא תַחְסֹם שׁוֹר בְּדִישׁוֹ\" – הַשּׁוֹר מֵרִיחַ אֶת הַתְּבוּאָה וּמִשְׁתּוֹקֵק לֶאֱכֹל, וְאָסוּר לְצַעֵר אוֹתוֹ. מִי שֶׁעוֹבֵד בִּשְׁבִילֵנוּ – רָאוּי שֶׁיֵּהָנֶה מֵעֲבוֹדָתוֹ.","פֶּרֶק ט״ו, הֲלָכָה ג׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["מָה עוֹשִׂים לְבָשָׂר חַי שֶׁלֹּא הֻכְשַׁר, לִפְנֵי שֶׁמְּבַשְּׁלִים אוֹתוֹ?",["מְבַשְּׁלִים מִיָּד כְּמוֹ שֶׁהוּא","מַשְׁרִים, מוֹלְחִים וְשׁוֹטְפִים","מְטַגְּנִים אוֹתוֹ בְּשֶׁמֶן"],1,"לִפְנֵי הַבִּשּׁוּל מַכְשִׁירִים אֶת הַבָּשָׂר: הֲדָחָה, מְלִיחָה וַהֲדָחָה. אִם מְבַשְּׁלִים אוֹ מְטַגְּנִים בְּלִי הַכְשָׁרָה, הַדָּם נִבְלָע בַּבָּשָׂר וְהוּא נֶאֱסָר.","פֶּרֶק כ״ב, הֲלָכוֹת ב׳, ה׳","בּוֹדְקִים וְנִזְהָרִים"],["אֵיךְ מַכְשִׁירִים כָּבֵד?",["צוֹלִים עַל אֵשׁ גְּלוּיָה","מוֹלְחִים כְּמוֹ בָּשָׂר רָגִיל","מְבַשְּׁלִים בְּסִיר מַיִם"],0,"הַכָּבֵד מָלֵא דָּם, וְהַמְּלִיחָה אֵינָהּ יְכוֹלָה לְהוֹצִיא אֶת כֻּלּוֹ. רַק צְלִיָּה עַל הָאֵשׁ מַכְשִׁירָה אוֹתוֹ.","פֶּרֶק כ״ב, הֲלָכָה י״ב","בּוֹדְקִים וְנִזְהָרִים"],["אַבָּא מֵכִין חֲבִיתָה מִשָּׁלֹשׁ בֵּיצִים. אֵיךְ כְּדַאי לִשְׁבֹּר אוֹתָן?",["יָשָׁר לְתוֹךְ הַמַּחֲבַת","כֻּלָּן לִקְעָרָה אַחַת","כָּל בֵּיצָה לְכוֹס נִפְרֶדֶת"],2,"כְּשֶׁשּׁוֹבְרִים בֵּיצִים מִסְתַּכְּלִים אִם יֵשׁ בָּהֶן דָּם. בְּכוֹס נִפְרֶדֶת – אִם תִּמָּצֵא בֵּיצָה עִם דָּם, זוֹרְקִים רַק אוֹתָהּ, וְלֹא אֶת כָּל הַשְּׁאָר.","פֶּרֶק כ״ד, הֲלָכָה ב׳","בּוֹדְקִים וְנִזְהָרִים"],["אֵיזֶה מַאֲכָל כָּשֵׁר, אַף שֶׁהוּא בָּא מִבַּעַל חַיִּים טָמֵא?",["חֲלֵב גְּמַלִּים","דְּבַשׁ","בֵּיצַת יַעֲנָה"],1,"הַיּוֹצֵא מִן הַטָּמֵא – טָמֵא: חֲלֵב גָּמָל וּבֵיצַת יַעֲנָה – אֲסוּרִים. הַדְּבַשׁ כָּשֵׁר, כִּי הַדְּבוֹרִים אוֹסְפוֹת אוֹתוֹ מִן הַפְּרָחִים, וְהוּא אֵינוֹ נוֹצָר בְּגוּפָן.","פֶּרֶק כ״ד, הֲלָכוֹת א׳, ד׳","בּוֹדְקִים וְנִזְהָרִים"],["אֵיךְ מְנַקִּים רֹאשׁ חַסָּה לַסָּלָט?",["שׁוֹטְפִים רַק אֶת הַחוּץ","מְנַעְנְעִים וּמְנַגְּבִים בְּמַגֶּבֶת","מְפָרְקִים לְעָלִים וְשׁוֹטְפִים"],2,"חֲרָקִים יְכוֹלִים לְהִסְתַּתֵּר בֵּין הֶעָלִים הַפְּנִימִיִּים. מְפָרְקִים אֶת הֶעָלִים כְּדֵי שֶׁהַמַּיִם יַגִּיעוּ לְכָל מָקוֹם, וְשׁוֹטְפִים הֵיטֵב.","פֶּרֶק כ״ג, הֲלָכָה י׳","בּוֹדְקִים וְנִזְהָרִים"],["לִפְנֵי שֶׁאוֹכְלִים תָּמָר, מָה עוֹשִׂים?",["פּוֹתְחִים וּמִסְתַּכְּלִים בִּפְנִים","אוֹכְלִים אוֹתוֹ שָׁלֵם","שׁוֹטְפִים רַק מִבַּחוּץ"],0,"בִּתְמָרִים, בִּתְאֵנִים וּבְמִשְׁמְשִׁים לִפְעָמִים יֵשׁ חֲרָקִים בִּפְנִים. לָכֵן פּוֹתְחִים אוֹתָם וּבוֹדְקִים לִפְנֵי הָאֲכִילָה.","פֶּרֶק כ״ג, הֲלָכָה י״ג","בּוֹדְקִים וְנִזְהָרִים"],["בַּחֲבִילַת צִמּוּקִים יֵשׁ קוּרִים לְבָנִים וַאֲבָקָה. מָה עוֹשִׂים?",["אוֹכְלִים מַהֵר, לִפְנֵי שֶׁיִּתְקַלְקְלוּ","שׁוֹטְפִים וְאוֹכְלִים מִיָּד","בּוֹדְקִים הֵיטֵב אוֹ זוֹרְקִים"],2,"קוּרִים וַאֲבָקָה הֵם סִימָן שֶׁיֵּשׁ חֲרָקִים. בּוֹדְקִים הֵיטֵב, וְלִפְעָמִים עָדִיף לִזְרֹק – כִּי הַבְּדִיקָה קָשָׁה.","פֶּרֶק כ״ג, הֲלָכָה י״ג","בּוֹדְקִים וְנִזְהָרִים"],["קָנוּ אֹרֶז בְּתִפְזֹרֶת בַּשּׁוּק. מָה עוֹשִׂים לִפְנֵי הַבִּשּׁוּל?",["מְבַשְּׁלִים כָּרָגִיל","מְפַזְּרִים עַל מַגָּשׁ וּבוֹדְקִים","מוֹסִיפִים מֶלַח לַסִּיר"],1,"אֹרֶז שֶׁנִּקְנָה בְּתִפְזֹרֶת עָלוּל לִהְיוֹת עִם חֲרָקִים, וּבוֹדְקִים אוֹתוֹ עַל מִשְׁטָח. אֹרֶז בַּאֲרִיזָה שֶׁל חֶבְרָה אֲמִינָה מֵחֲנוּת נְקִיָּה – אֵין צֹרֶךְ לִבְדֹּק.","פֶּרֶק כ״ג, הֲלָכָה י״ד","בּוֹדְקִים וְנִזְהָרִים"],["שַׂקִּית קֶמַח עָמְדָה פְּתוּחָה עַל הַשַּׁיִשׁ יוֹם שָׁלֵם. מָה עוֹשִׂים לִפְנֵי הָאֲפִיָּה?",["מְנַפִּים אוֹתוֹ בְּנָפָה","שׁוֹפְכִים יָשָׁר לַקְּעָרָה","מוֹסִיפִים עוֹד שְׁמָרִים"],0,"קֶמַח שֶׁעָמַד פָּתוּחַ יְמָמָה – וּבְיוֹם חַם אֲפִלּוּ כַּמָּה שָׁעוֹת – עָלוּל לְהַתְלִיעַ, וְצָרִיךְ לְנַפּוֹת אוֹתוֹ.","פֶּרֶק כ״ג, הֲלָכָה ט״ז","בּוֹדְקִים וְנִזְהָרִים"],["אֵיזוֹ אֲכִילָה שׁוֹמֶרֶת עַל הַמִּצְוָה \"אַל תְּשַׁקְּצוּ\"?",["אֹכֶל שֶׁנִּשְׁלַף מִן הַפַּח","אֲכִילָה בְּנִקָּיוֹן וּבְנִימוּס","לְלַקֵּק אֹכֶל מִן הָרִצְפָּה"],1,"\"אַל תְּשַׁקְּצוּ אֶת נַפְשֹׁתֵיכֶם\" – אָסוּר לֶאֱכֹל דְּבָרִים מְאוּסִים, אוֹ לֶאֱכֹל בְּדֶרֶךְ שֶׁמְּעוֹרֶרֶת גֹּעַל.","פֶּרֶק כ״ג, הֲלָכָה ב׳","בּוֹדְקִים וְנִזְהָרִים"],["מָה אָסוּר לְבַשֵּׁל יַחַד בְּסִיר אֶחָד?",["בָּשָׂר וְתַפּוּחֵי אֲדָמָה","בָּשָׂר וְחָלָב","יְרָקוֹת וּגְבִינָה"],1,"\"לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ\" – אָסוּר לְבַשֵּׁל בָּשָׂר עִם חָלָב. בָּשָׂר עִם יְרָקוֹת, וִירָקוֹת עִם גְּבִינָה – מֻתָּרִים.","פֶּרֶק כ״ה, הֲלָכָה א׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["מָה מֻתָּר לִשְׁתּוֹת עִם שְׁנִיצֶל עוֹף?",["כּוֹס חָלָב","שׁוֹקוֹ","מִיץ תַּפּוּזִים"],2,"גַּם בְּשַׂר עוֹף אָסוּר לֶאֱכֹל עִם חָלָב, מִדִּבְרֵי חֲכָמִים. מִיץ תַּפּוּזִים הוּא פַּרְוֶה, וְהוּא מֻתָּר.","פֶּרֶק כ״ה, הֲלָכָה ב׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["מֵאֵיזוֹ מְגֵרָה לוֹקְחִים כַּף לִמְרַק עוֹף?",["מִן הַמְּגֵרָה הַבְּשָׂרִית","מִן הַמְּגֵרָה הֶחָלָבִית","כַּף שֶׁאָכְלוּ בָּהּ יוֹגוּרְט"],0,"לְמַאֲכָל בְּשָׂרִי מְשַׁמְּשִׁים בְּכֵלִים בְּשָׂרִיִּים, וּלְמַאֲכָל חֲלָבִי – בְּכֵלִים חֲלָבִיִּים. הַהֶבְדֵּל הַבּוֹלֵט בֵּין הַכֵּלִים עוֹזֵר שֶׁלֹּא יִתְחַלְּפוּ.","פֶּרֶק כ״ה, הֲלָכָה ז׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בַּמִּטְבָּח שְׁנֵי כִּיּוֹרִים. אֵיפֹה שׁוֹטְפִים סִיר שֶׁבִּשְּׁלוּ בּוֹ פַּסְטָה בִּגְבִינָה?",["בַּכִּיּוֹר הֶחָלָבִי","בַּכִּיּוֹר הַבְּשָׂרִי","יַחַד עִם סִירֵי הַבָּשָׂר"],0,"נוֹהֲגִים בִּשְׁנֵי כִּיּוֹרִים – לְחָלָב וּלְבָשָׂר. אֶת הַכֵּלִים הַחֲלָבִיִּים שׁוֹטְפִים בַּכִּיּוֹר הֶחָלָבִי, וְלֹא יַחַד עִם כְּלֵי בָּשָׂר.","פֶּרֶק כ״ה, הֲלָכָה י״ב","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אֵיזֶה מַאֲכָל הוּא פַּרְוֶה?",["תַּפּוּחַ","גְּבִינָה","נַקְנִיק"],0,"פַּרְוֶה – לֹא בְּשָׂרִי וְלֹא חֲלָבִי. אֶת הַתַּפּוּחַ אֶפְשָׁר לֶאֱכֹל גַּם בַּאֲרוּחָה בְּשָׂרִית וְגַם בַּאֲרוּחָה חֲלָבִית.","פֶּרֶק כ״ה, הֲלָכָה ח׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אוֹכְלִים עוֹף בַּאֲרוּחַת שַׁבָּת, וְאָחִיךָ הַקָּטָן הֵבִיא לַשֻּׁלְחָן קַרְטוֹן חָלָב. מָה עוֹשִׂים?",["שׁוֹתִים מִמֶּנּוּ מְעַט","מַחְזִירִים אוֹתוֹ לַמְּקָרֵר","מַשְׁאִירִים אוֹתוֹ לְיַד הָעוֹף"],1,"בִּזְמַן אֲרוּחַת בָּשָׂר לֹא מַנִּיחִים חָלָב עַל הַשֻּׁלְחָן – שֶׁמָּא יִטְעוּ וְיֹאכְלוּ אוֹתָם יַחַד.","פֶּרֶק כ״ה, הֲלָכָה ג׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אַחֲרֵי פִּיצָה בִּגְבִינָה, נֹעַם רוֹצֶה לֶאֱכֹל קְצִיצָה. מָה הוּא עוֹשֶׂה קֹדֶם?",["מְצַחְצֵחַ שִׁנַּיִם וְשׁוֹטֵף אֶת הַפֶּה","אוֹכֵל אֶת הַקְּצִיצָה מִיָּד","מְנַגֵּב אֶת הַפֶּה בְּמַפִּית"],0,"אַחֲרֵי חָלָב מְנַקִּים אֶת הַפֶּה – בְּמַאֲכָל מוּצָק וּשְׁתִיָּה, אוֹ בְּצִחְצוּחַ שִׁנַּיִם וּשְׁטִיפָה, שֶׁהֵם טוֹבִים עוֹד יוֹתֵר. וּבוֹדְקִים שֶׁהַיָּדַיִם נְקִיּוֹת.","פֶּרֶק כ״ו, הֲלָכָה א׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בַּצָּהֳרַיִם אָכַל דָּוִד שְׁנִיצֶל, וְעַכְשָׁו מַצִּיעִים לוֹ גְּלִידָה חֲלָבִית. מָה הַדִּין?",["אוֹכֵל מִיָּד","שׁוֹטֵף אֶת הַפֶּה וְאוֹכֵל","מְחַכֶּה לְפִי הַמִּנְהָג"],2,"אַחֲרֵי בָּשָׂר לֹא מַסְפִּיק לִשְׁטֹף אֶת הַפֶּה – מַמְתִּינִים. כָּל אֶחָד לְפִי מִנְהַג מִשְׁפַּחְתּוֹ.","פֶּרֶק כ״ו, הֲלָכָה ב׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אַבָּא לָשׁ בָּצֵק לְלַחְמָנִיּוֹת לְכָל הַשָּׁבוּעַ. בְּמָה הוּא לָשׁ אוֹתוֹ?",["בְּחָלָב","בְּשׁוּמַן בָּשָׂר","בְּמַיִם"],2,"לֶחֶם לְכַמָּה סְעוּדוֹת לֹא לָשִׁים בְּחָלָב אוֹ בְּשׁוּמַן בָּשָׂר, שֶׁמָּא יִשְׁכְּחוּ וְיֹאכְלוּ אוֹתוֹ עִם הַמִּין הַשֵּׁנִי.","פֶּרֶק כ״ה, הֲלָכָה ד׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["שְׁנֵי חֲבֵרִים יוֹשְׁבִים לְיַד אוֹתוֹ שֻׁלְחָן: אֶחָד אוֹכֵל פַּסְטָה בִּגְבִינָה, וְהַשֵּׁנִי – קְצִיצוֹת. מָה עוֹשִׂים?",["אוֹכְלִים מֵאוֹתָהּ צַלַּחַת","שָׂמִים מַפָּה נִפְרֶדֶת לְאֶחָד","מַחֲלִיפִים בֵּינֵיהֶם בִּיסִים"],1,"שְׁנֵי אֲנָשִׁים שֶׁמַּכִּירִים זֶה אֶת זֶה וְאוֹכְלִים זֶה בָּשָׂר וְזֶה חָלָב – צְרִיכִים סִימָן בֵּינֵיהֶם, כְּמוֹ מַפָּה נִפְרֶדֶת, כְּדֵי שֶׁלֹּא יִקַּח אֶחָד מִמַּאֲכַל חֲבֵרוֹ.","פֶּרֶק כ״ה, הֲלָכָה ג׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אַבָּא קָנָה כֵּלִים חֲדָשִׁים שֶׁיֻּצְּרוּ אֵצֶל גּוֹיִם. אֵיזֶה מֵהֶם צָרִיךְ טְבִילָה?",["כַּף מֵעֵץ","סִיר מִמַּתֶּכֶת","כּוֹס מִפְּלַסְטִיק"],1,"כְּלִי אֹכֶל מִמַּתֶּכֶת טוֹבְלִים בְּמִקְוֶה לִפְנֵי הַשִּׁמּוּשׁ. כֵּלִים מֵעֵץ וּמִפְּלַסְטִיק פְּטוּרִים מִטְּבִילָה.","פֶּרֶק ל״א, הֲלָכוֹת א׳–ב׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["עַל שֻׁלְחַן הַשַּׁבָּת מֻנַּחַת חַלָּה, וְדָנִי מַעֲבִיר כּוֹס מִיץ מְלֵאָה לְאָחִיו. אֵיךְ נָכוֹן לְהַעֲבִיר?",["יְשִׁירוֹת מֵעַל הַחַלָּה","מַנִּיחַ אֶת הַכּוֹס עַל הַחַלָּה","מִסָּבִיב לַחַלָּה"],2,"לֹא מַעֲבִירִים כּוֹס מְלֵאָה מֵעַל לֶחֶם, שֶׁמָּא תִּשָּׁפֵךְ וְתַשְׁחִית אוֹתוֹ. וְגַם לֹא מַנִּיחִים עַל הַלֶּחֶם כְּלִי שֶׁעָלוּל לְלַכְלֵךְ אוֹתוֹ.","פֶּרֶק י״ג, הֲלָכָה ט׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["אַחֲרֵי בַּר הַמִּצְוָה שֶׁל אָחִיךָ נִשְׁאַר הַרְבֵּה אֹכֶל טָעִים. מָה עוֹשִׂים?",["שׁוֹמְרִים בַּמְּקָרֵר וּמְחַלְּקִים","זוֹרְקִים הַכֹּל לַפַּח","מַשְׁאִירִים עַל הַשֻּׁלְחָן לְמָחָר"],0,"אָסוּר לִזְרֹק אֹכֶל טוֹב. שׁוֹמְרִים אוֹתוֹ בַּמְּקָרֵר, וּמְחַלְּקִים לִקְרוֹבִים, לִשְׁכֵנִים אוֹ לַעֲנִיִּים. וְאֹכֶל שֶׁנִּשְׁאָר בַּחוּץ עָלוּל לְהִתְקַלְקֵל.","פֶּרֶק י״ג, הֲלָכָה י׳; פֶּרֶק ל״ו, הֲלָכָה ג׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בְּסוֹף הָאֲרוּחָה יֵשׁ פֵּרוּרִים עַל הַשֻּׁלְחָן. מָה הַדֶּרֶךְ הַנְּכוֹנָה?",["מְטַאטְאִים אוֹתָם לָרִצְפָּה","אוֹסְפִים אוֹתָם לַפַּח","מַרְטִיבִים אוֹתָם בַּמַּטְלִית"],1,"פֵּרוּרִים אוֹסְפִים לַפַּח, וְלֹא מַשְׁלִיכִים לָרִצְפָּה. וַחֲתִיכוֹת לֶחֶם גְּדוֹלוֹת לֹא מַרְטִיבִים בִּשְׁטִיפַת הַשֻּׁלְחָן, אֶלָּא עוֹטְפִים וּמַנִּיחִים בַּפַּח.","פֶּרֶק י״ג, הֲלָכָה י״ב","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["אַבָּא חָתַךְ עוֹף חַי, וְעַכְשָׁו הוּא רוֹצֶה לְהָכִין סָלָט. מָה עָלָיו לַעֲשׂוֹת קֹדֶם?",["לְנַגֵּב אֶת הַיָּדַיִם בַּסִּינָר","לְהַתְחִיל מִיָּד לַחְתֹּךְ יְרָקוֹת","לִשְׁטֹף יָדַיִם בְּמַיִם וְסַבּוֹן"],2,"בְּבָשָׂר חַי יֵשׁ חַיְדַּקִּים. הַבִּשּׁוּל הוֹרֵג אוֹתָם בָּאֹכֶל, אֲבָל לֹא עַל הַיָּדַיִם – לָכֵן שׁוֹטְפִים מִיָּד בְּמַיִם וְסַבּוֹן.","פֶּרֶק ל״ו, הֲלָכָה ג׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בַּחֲנוּת יֵשׁ שְׁלוֹשָׁה סוּגֵי סֻכָּרִיּוֹת. אֵיזוֹ שַׂקִּית כְּדַאי לִקְנוֹת?",["שַׂקִּית עִם סֵמֶל כַּשְׁרוּת","הַשַּׂקִּית הַצִּבְעוֹנִית בְּיוֹתֵר","הַשַּׂקִּית הַגְּדוֹלָה בְּיוֹתֵר"],0,"בְּסֻכָּרִיּוֹת יֵשׁ לִפְעָמִים גֶ׳לָטִין אוֹ צִבְעֵי מַאֲכָל מִבַּעֲלֵי חַיִּים אֲסוּרִים. לָכֵן קוֹנִים רַק מוּצָר שֶׁיֵּשׁ לוֹ הֶכְשֵׁר.","פֶּרֶק ל״ז, הֲלָכוֹת א׳, ג׳, ה׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["הַמְּעִיל שֶׁל מֹשֶׁה קָטָן עָלָיו, אֲבָל הוּא עוֹד יָפֶה וְשָׁלֵם. מָה הֲכִי טוֹב לַעֲשׂוֹת?",["לַחְתֹּךְ אוֹתוֹ לִסְמַרְטוּטִים","לִזְרֹק אוֹתוֹ לַפַּח","לָתֵת אוֹתוֹ לְמִי שֶׁיִּלְבַּשׁ"],2,"מֻתָּר לְהַפְסִיק לִלְבֹּשׁ בֶּגֶד, אֲבָל מִצְוָה לִמְצֹא מִי שֶׁיֵּהָנֶה מִמֶּנּוּ. וְאִם נוֹתְנִים אוֹתוֹ לְעָנִי – מְקַיְּמִים גַּם מִצְוַת צְדָקָה.","פֶּרֶק י״ג, הֲלָכָה י״א","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בַּסְּעוּדָה אָכַלְתָּ דָּג, וְעַכְשָׁו מַגִּישִׁים בָּשָׂר. מָה עוֹשִׂים?",["שָׂמִים אֶת הַבָּשָׂר בְּאוֹתָהּ צַלַּחַת","לוֹקְחִים צַלַּחַת וּמַזְלֵג חֲדָשִׁים","מְעַרְבְּבִים אֶת שְׁנֵיהֶם יַחַד"],1,"נָהֲגוּ יִשְׂרָאֵל לֹא לֶאֱכֹל בָּשָׂר וְדָגִים יַחַד. לָכֵן מַחְלִיפִים צַלַּחַת וְסַכּוּ״ם, וְשׁוֹתִים מַשֶּׁהוּ בֵּין הַדָּג לַבָּשָׂר.","פֶּרֶק ל״ו, הֲלָכָה ד׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["מָתַי מֻתָּר לִשְׁבֹּר כְּלִי בְּכַוָּנָה?",["הֶחָתָן שׁוֹבֵר כּוֹס בַּחֻפָּה","שׁוֹבְרִים צַלַּחַת מִתּוֹךְ כַּעַס","בּוֹעֲטִים בְּכִסֵּא לְשֵׁם שַׁעֲשׁוּעַ"],0,"הַשְּׁבִירָה בַּחֻפָּה הִיא מִצְוָה – לִזְכֹּר אֶת חֻרְבַּן הַמִּקְדָּשׁ גַּם בְּשִׂמְחָה. אֲבָל לִשְׁבֹּר בְּכַעַס אוֹ בִּשְׁבִיל הַשַּׁעֲשׁוּעַ – אָסוּר.","פֶּרֶק י״ג, הֲלָכוֹת ז׳–ח׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["יְלָדִים מְטַיְּלִים בְּגִנָּה צִבּוּרִית. מִי מִתְנַהֵג כַּהֲלָכָה?",["שׁוֹבֵר עָנָף מֵהָעֵץ","חוֹרֵט סִימָנִים עַל הַגֶּזַע","זוֹרֵק עֲטִיפָה לַפַּח"],2,"לָעֵצִים וְלַפְּרָחִים שֶׁבַּגִּנָּה יֵשׁ עֵרֶךְ, וְהֵם גַּם מְטַהֲרִים אֶת הָאֲוִיר – הַמַּשְׁחִית אוֹתָם עוֹבֵר עַל אִסּוּר. וּמִצְוָה לִשְׁמֹר עַל נִקְיוֹן הַטֶּבַע.","פֶּרֶק י״ג, הֲלָכָה י״ג","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בֶּחָצֵר יֵשׁ עֵץ תַּפּוּחִים שֶׁנִּטַּע לִפְנֵי שְׁנָתַיִם, וּכְבָר יֵשׁ עָלָיו פֵּרוֹת. מָה עוֹשִׂים בָּהֶם?",["אוֹכְלִים אוֹתָם","מַשְׁאִירִים אוֹתָם וְלֹא נֶהֱנִים","נוֹתְנִים אוֹתָם לַשָּׁכֵן"],1,"פֵּרוֹת שֶׁל שָׁלֹשׁ הַשָּׁנִים הָרִאשׁוֹנוֹת הֵם עָרְלָה – אָסוּר לֶאֱכֹל אוֹתָם וְאָסוּר לֵהָנוֹת מֵהֶם, וְלָכֵן גַּם לֹא נוֹתְנִים אוֹתָם לְאַחֵר.","פֶּרֶק ב׳, הֲלָכוֹת א׳, ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["לְאֵיזֶה צֶמַח יֵשׁ דִּין עָרְלָה?",["עֵץ תְּאֵנָה","צֶמַח בָּנָנָה","שִׂיחַ עַגְבָנִיּוֹת"],0,"עָרְלָה חָלָה רַק עַל עֵץ שֶׁגִּזְעוֹ נִשְׁאָר שָׁנִים רַבּוֹת. הַבָּנָנָה צוֹמַחַת מֵחָדָשׁ כָּל שָׁנָה וְנֶחְשֶׁבֶת יָרָק, וְעַל יְרָקוֹת אֵין עָרְלָה.","פֶּרֶק ב׳, הֲלָכָה ח׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בִּזְמַן הַקָּצִיר נָפְלָה שִׁבֹּלֶת אַחַת מִיַּד הַקּוֹצֵר. מָה עוֹשֶׂה בַּעַל הַשָּׂדֶה?",["מֵרִים אוֹתָהּ לְעַצְמוֹ","מַאֲכִיל בָּהּ אֶת הַפָּרָה","מַשְׁאִיר אוֹתָהּ לָעֲנִיִּים"],2,"שִׁבֹּלֶת אַחַת אוֹ שְׁתַּיִם שֶׁנָּפְלוּ בִּזְמַן הַקָּצִיר הֵן \"לֶקֶט\", וְהֵן שַׁיָּכוֹת לָעֲנִיִּים.","פֶּרֶק ו׳, הֲלָכוֹת א׳, ה׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["הַחַקְלַאי סִיֵּם לֶאֱסֹף, וּפִתְאֹם רָאָה עֹמֶר שֶׁשָּׁכַח בַּשָּׂדֶה. מָה עָלָיו לַעֲשׂוֹת?",["חוֹזֵר וְלוֹקֵחַ אוֹתוֹ","מַשְׁאִיר אוֹתוֹ לָעֲנִיִּים","שׁוֹלֵחַ פּוֹעֵל לְהָבִיא אוֹתוֹ"],1,"\"וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה – לֹא תָשׁוּב לְקַחְתּוֹ\". מַה שֶּׁנִּשְׁכַּח שַׁיָּךְ לָעֲנִיִּים, וְזוֹ מִצְוָה שֶׁה׳ מְזַמֵּן.","פֶּרֶק ו׳, הֲלָכָה ד׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["אֵיפֹה מַשְׁאִירִים אֶת הַפֵּאָה לָעֲנִיִּים?",["בְּסוֹף הַשָּׂדֶה","בְּאֶמְצַע הַשָּׂדֶה","בַּמָּקוֹם הַגָּרוּעַ בְּיוֹתֵר"],0,"\"לֹא תְכַלֶּה פְּאַת שָׂדְךָ\" – מַשְׁאִירִים בְּסוֹף הַקָּצִיר. כָּךְ הָעֲנִיִּים יוֹדְעִים מָתַי לָבוֹא, וּבַעַל הַשָּׂדֶה לֹא בּוֹחֵר דַּוְקָא אֶת הַגָּרוּעַ.","פֶּרֶק ו׳, הֲלָכָה ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּבָּצִיר נִשְׁאֲרוּ עַל הַגֶּפֶן אֶשְׁכּוֹלוֹת קְטַנְטַנִּים. מָה עוֹשִׂים בָּהֶם?",["בּוֹצְרִים אוֹתָם לַיַּיִן","זוֹרְקִים אוֹתָם לָעִזִּים","מַשְׁאִירִים אוֹתָם לָעֲנִיִּים"],2,"\"וְכַרְמְךָ לֹא תְעוֹלֵל\" – אֶשְׁכּוֹלוֹת קְטַנְטַנִּים הֵם \"עוֹלְלוֹת\", וּמַשְׁאִירִים אוֹתָם לָעֲנִיִּים. וְכֵן עֲנָבִים בּוֹדְדִים שֶׁנָּפְלוּ – \"פֶּרֶט\".","פֶּרֶק ו׳, הֲלָכָה ו׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["אַבָּא הִפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת מִן הַפֵּרוֹת. מָה הוּא עוֹשֶׂה בַּחֲתִיכַת הַתְּרוּמָה?",["עוֹטֵף וּמַנִּיחַ בַּפַּח","אוֹכֵל אוֹתָהּ בְּעַצְמוֹ","זוֹרֵק אוֹתָהּ לָרְחוֹב"],0,"הַיּוֹם הַכֹּהֲנִים אֵינָם יְכוֹלִים לֶאֱכֹל תְּרוּמָה, וּלְמִי שֶׁאֵינוֹ כֹּהֵן הִיא אֲסוּרָה. לָכֵן עוֹטְפִים אוֹתָהּ וּמַנִּיחִים בַּפַּח בְּדֶרֶךְ כָּבוֹד.","פֶּרֶק ט׳, הֲלָכָה ה׳; פֶּרֶק י׳, הֲלָכָה א׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["אַבָּא וְיוֹנָתָן אוֹפִים חַלּוֹת לְשַׁבָּת. מָתַי מַפְרִישִׁים חַלָּה?",["כְּשֶׁהַקֶּמַח עוֹד בַּשַּׂק","אַחֲרֵי שֶׁלָּשִׁים אֶת הַבָּצֵק","רַק בְּשַׁבָּת עַצְמָהּ"],1,"חוֹבַת הַחַלָּה מַתְחִילָה כְּשֶׁמְּעַרְבְּבִים קֶמַח וּמַיִם, וְהַזְּמַן הַמֻּבְחָר הוּא בְּסוֹף הַלִּישָׁה. וּבְשַׁבָּת אָסוּר לְהַפְרִישׁ חַלָּה.","פֶּרֶק י״א, הֲלָכוֹת ה׳, י״ג","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["מִשְׁפָּחָה בְּאֶרֶץ יִשְׂרָאֵל קוֹנָה פֵּרוֹת וִירָקוֹת. אֵיפֹה נָכוֹן לִקְנוֹת?",["בְּדוּכָן בְּלִי שׁוּם הַשְׁגָּחָה","מֵעֵץ שֶׁל שָׁכֵן בְּלִי רְשׁוּת","בַּחֲנוּת עִם תְּעוּדַת כַּשְׁרוּת"],2,"בַּפֵּרוֹת שֶׁל הָאָרֶץ צָרִיךְ לִדְאֹג לְעָרְלָה וְלִתְרוּמוֹת וּמַעַשְׂרוֹת. כְּשֶׁיֵּשׁ חֲנוּת עִם תְּעוּדַת כַּשְׁרוּת – קוֹנִים בָּהּ. וְלָקַחַת בְּלִי רְשׁוּת – זוֹ גְּנֵבָה.","פֶּרֶק ב׳, הֲלָכָה י״א","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["מֵאֵיזֶה בָּצֵק מַפְרִישִׁים חַלָּה?",["בָּצֵק מִקֶּמַח חִטָּה","בָּצֵק מִקֶּמַח אֹרֶז","בָּצֵק מִקֶּמַח תִּירָס"],0,"חַלָּה מַפְרִישִׁים רַק מִבָּצֵק שֶׁל חֲמֵשֶׁת מִינֵי דָּגָן, שֶׁאֶפְשָׁר לַעֲשׂוֹת מֵהֶם לֶחֶם. אֹרֶז וְתִירָס אֵינָם מִן הַמִּינִים הָאֵלֶּה.","פֶּרֶק י״א, הֲלָכָה ט׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["אֵיזֶה חָלָב כָּשֵׁר לִשְׁתִיָּה?",["חֲלֵב פָּרָה","חֲלֵב סוּסָה","חֲלֵב אָתוֹן"],0,"הַיּוֹצֵא מִן הַטָּהוֹר – טָהוֹר: חֲלֵב פָּרָה וְעֵז כָּשֵׁר. סוּסָה וְאָתוֹן הֵן בְּהֵמוֹת טְמֵאוֹת, וְגַם הֶחָלָב שֶׁלָּהֶן טָמֵא.","פֶּרֶק ל׳, הֲלָכָה א׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["מָה אָכְלוּ דָּנִיֵּאל וַחֲבֵרָיו בְּאַרְמוֹן מֶלֶךְ בָּבֶל?",["בָּשָׂר מִשֻּׁלְחַן הַמֶּלֶךְ","עוּגוֹת הַמֶּלֶךְ","זֵרְעוֹנִים וְקִטְנִיּוֹת"],2,"דָּנִיֵּאל וַחֲבֵרָיו לֹא אָכְלוּ מִפַּת הַמֶּלֶךְ, מִיֵּינוֹ וּמִשַּׁמְנוֹ, וְהִסְתַּפְּקוּ בְּזֵרְעוֹנִים וּבְקִטְנִיּוֹת – וְנִרְאוּ בְּרִיאִים מִכָּל הַנְּעָרִים.","פֶּרֶק כ״ז, הֲלָכָה ג׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["חֲכָמִים גָּזְרוּ עַל כַּמָּה מַאַכְלֵי גּוֹיִם. אֵיזֶה מֵהֶם הִתִּירוּ לְבַסּוֹף?",["תַּבְשִׁיל שֶׁל גּוֹי","שֶׁמֶן שֶׁל גּוֹי","גְּבִינָה שֶׁל גּוֹי"],1,"רֹב יִשְׂרָאֵל לֹא יָכְלוּ לַעֲמֹד בִּגְזֵרַת הַשֶּׁמֶן, וְרַבִּי יְהוּדָה נְשִׂיאָה וּבֵית דִּינוֹ הִתִּירוּ אוֹתוֹ. בִּשּׁוּלֵי גּוֹיִם וּגְבִינַת גּוֹיִם – נִשְׁאֲרוּ אֲסוּרִים.","פֶּרֶק כ״ז, הֲלָכוֹת ה׳–ו׳; פֶּרֶק ל׳, הֲלָכָה ז׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["בְּשַׁבָּת הַפָּרוֹת בָּרֶפֶת צְרִיכוֹת חֲלִיבָה. מָה מֻתָּר?",["יְהוּדִי חוֹלֵב בְּיָדָיו","לֹא חוֹלְבִים, שֶׁיִּצְטַעֲרוּ","גּוֹי חוֹלֵב אוֹתָן"],2,"חֲלִיבָה בְּשַׁבָּת אֲסוּרָה מִן הַתּוֹרָה. אֲבָל מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים מֻתָּר לְבַקֵּשׁ מִגּוֹי לַחֲלֹב, וְהֶחָלָב מֻתָּר אַחֲרֵי הַשַּׁבָּת.","פֶּרֶק ל׳, הֲלָכָה י״א","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["גּוֹי חוֹלֵב פָּרָה. מָתַי הֶחָלָב כָּשֵׁר לְכָל הַדֵּעוֹת?",["כְּשֶׁיְּהוּדִי מַשְׁגִּיחַ","כְּשֶׁהַגּוֹי מַבְטִיחַ","כְּשֶׁהֶחָלָב לָבָן מְאוֹד"],0,"כְּשֶׁיְּהוּדִי מַשְׁגִּיחַ – וְהַגּוֹי יוֹדֵעַ שֶׁהוּא יָכוֹל לִרְאוֹתוֹ בְּכָל רֶגַע – הֶחָלָב כָּשֵׁר. חֲכָמִים הֶחְמִירוּ וְלֹא סָמְכוּ עַל הַבְטָחָה אוֹ עַל צֶבַע הֶחָלָב.","פֶּרֶק ל׳, הֲלָכָה ב׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["חֲתִיכַת בָּשָׂר לֹא כְּשֵׁרָה נָפְלָה לְסִיר גָּדוֹל שֶׁל מְרַק יְרָקוֹת. מָה עוֹשִׂים מִיָּד?",["מוֹסִיפִים מַיִם לַסִּיר","מוֹצִיאִים אֶת הַחֲתִיכָה","מְעַרְבְּבִים הֵיטֵב"],1,"אֶת הַחֲתִיכָה שֶׁאֶפְשָׁר לִרְאוֹת – חוֹבָה לְהוֹצִיא. אִם יֵשׁ בַּמָּרָק פִּי שִׁשִּׁים מִמֶּנָּה – הַמָּרָק כָּשֵׁר. וְאָסוּר לְהוֹסִיף מַיִם כְּדֵי לְבַטֵּל אֶת הָאִסּוּר.","פֶּרֶק ל״ד, הֲלָכוֹת ג׳, י״ג","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["אֵיזוֹ גְּבִינָה מֻתֶּרֶת?",["גְּבִינָה שֶׁגּוֹי הֵכִין","גּוֹי מֵכִין מֵחָלָב כָּשֵׁר","גְּבִינָה שֶׁיְּהוּדִי הֵכִין"],2,"חֲכָמִים אָסְרוּ כָּל גְּבִינָה שֶׁגּוֹי הֵכִין – גַּם כְּשֶׁהֶחָלָב כָּשֵׁר, וְגַם כְּשֶׁהִיא מְגֻבֶּנֶת בְּחֹמָרִים כְּשֵׁרִים.","פֶּרֶק ל׳, הֲלָכָה ז׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["בְּטָעוּת עֵרְבְבוּ תַּבְשִׁיל בְּשָׂרִי רוֹתֵחַ בְּכַף מַתֶּכֶת חֲלָבִית נְקִיָּה. מָה צָרִיךְ הַכְשָׁרָה?",["אֶת הַכַּף","אֶת הַתַּבְשִׁיל","אֶת כָּל הַמִּטְבָּח"],0,"כַּף מַתֶּכֶת נְקִיָּה אֵינָהּ פּוֹלֶטֶת טְעָמִים, וְלָכֵן הַתַּבְשִׁיל כָּשֵׁר. אֲבָל הַכַּף בָּלְעָה גַּם בָּשָׂר וְגַם חָלָב – וְהִיא צְרִיכָה הַגְעָלָה.","פֶּרֶק ל״ב, הֲלָכָה י״ד","עַם מְיֻחָד גַּם בַּמִּטְבָּח"]],"b":[["שְׁנֵי חֲבֵרִים מְבַקְּשִׁים עֶזְרָה בְּאוֹתוֹ רֶגַע: אֶחָד – לְהוֹרִיד מַשָּׂא מֵחֲמוֹר שֶׁנָּפַל, וְהַשֵּׁנִי – לְהַעֲמִיס מַשָּׂא עַל חֲמוֹרוֹ. לְמִי עוֹזְרִים קֹדֶם?",["לָרִאשׁוֹן, כְּדֵי לְהָקֵל מִיָּד עַל צַעַר הַחֲמוֹר","לַשֵּׁנִי, כִּי טְעִינָה חֲשׁוּבָה תָּמִיד יוֹתֵר מִפְּרִיקָה","לְמִי שֶׁבִּקֵּשׁ רִאשׁוֹן, כִּי כָּךְ הוּא הַסֵּדֶר","לְמִי שֶׁמּוּכָן לְשַׁלֵּם לְךָ יוֹתֵר עַל הָעֶזְרָה"],0,"פְּרִיקָה קוֹדֶמֶת לִטְעִינָה, כִּי הַחֲמוֹר שֶׁנָּפַל סוֹבֵל עַכְשָׁו. וּבִפְרִיקָה עוֹזְרִים גַּם בְּחִנָּם, כְּדֵי לְהַצִּיל אֶת הַחֲמוֹר מִצַּעַר.","פֶּרֶק ט״ו, הֲלָכָה ב׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["לַשָּׁכֵן יֵשׁ כֶּלֶב גָּדוֹל וְטוֹב, אֲבָל הוּא נוֹבֵחַ בְּקוֹל עַל כָּל מִי שֶׁעוֹבֵר בַּשְּׁבִיל, וְהַיְּלָדִים מְפַחֲדִים. מָה הַדִּין?",["מֻתָּר, כִּי הַכֶּלֶב מְאֻלָּף וּבֶאֱמֶת אֵינוֹ נוֹשֵׁךְ אַף אֶחָד","אָסוּר, אֶלָּא אִם כֵּן הוּא קָשׁוּר אוֹ מְגֻדָּר","מֻתָּר, כִּי כָּל אֶחָד רַשַּׁאי לִשְׁמֹר עַל חֲצֵרוֹ","אָסוּר לְגַדֵּל כֶּלֶב גָּדוֹל בְּשׁוּם מָקוֹם וּבְשׁוּם מַצָּב"],1,"אָסוּר לְגַדֵּל כֶּלֶב שֶׁמַּפְחִיד אֶת הָעוֹבְרִים, גַּם אִם הוּא מְאֻלָּף. כְּשֶׁכֻּלָּם רוֹאִים שֶׁהוּא קָשׁוּר אוֹ מְגֻדָּר – אֵין מִמָּה לְפַחֵד, וּמֻתָּר.","פֶּרֶק ט״ו, הֲלָכָה י״א","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["שִׁמְעוֹן מָצָא בַּגִּנָּה הַצִּבּוּרִית קֵן שֶׁל יוֹנַת בָּר. הוּא אֵינוֹ צָרִיךְ אֶת הַבֵּיצִים, אֲבָל רוֹצֶה לָצֵאת יְדֵי כָּל הַדֵּעוֹת. מָה יַעֲשֶׂה?",["יְשַׁלַּח אֶת הָאֵם, וְיִקַּח אֶת כָּל הַבֵּיצִים הַבַּיְתָה","יַבְרִיחַ אֶת הָאֵם בְּקוֹל, וְלֹא יִקַּח אֶת הַבֵּיצִים","יִקַּח אֶת הַקֵּן כֻּלּוֹ, יַחַד עִם הָאֵם וְהַבֵּיצִים","יְחַכֶּה שֶׁהָאֵם תֵּלֵךְ, וְיִקַּח אֶת הַבֵּיצִים בְּלִי לְשַׁלֵּחַ"],1,"יֵשׁ אוֹמְרִים שֶׁכְּבָר בְּהַבְרָחַת הָאֵם מְקַיְּמִים אֶת הַמִּצְוָה. וְכֵיוָן שֶׁאֵינוֹ צָרִיךְ אֶת הַבֵּיצִים – לֹא יִקַּח אוֹתָן, כְּדֵי שֶׁלֹּא לְצַעֵר וּלְהַשְׁחִית בְּחִנָּם.","פֶּרֶק ט״ז, הֲלָכָה ג׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["אֵיזֶה מִן הַבִּלּוּיִים הָאֵלֶּה מֻתָּר לִיהוּדִי?",["לָצוּד צִפּוֹרִים בַּיַּעַר רַק לְשֵׁם סְפּוֹרְט וְשַׁעֲשׁוּעַ","לִקְנוֹת כַּרְטִיס לְמוֹפָע גָּדוֹל שֶׁל מִלְחֶמֶת תַּרְנְגוֹלִים","לָדוּג דָּגִים בְּחַכָּה כְּדֵי לֶאֱכֹל אוֹתָם בָּאֲרוּחָה","לִצְפּוֹת בְּמִלְחֶמֶת שְׁוָרִים גְּדוֹלָה בְּטִיּוּל בְּחוּץ לָאָרֶץ"],2,"דַּיִג לְשֵׁם אֲכִילָה הוּא צֹרֶךְ אֲמִתִּי, וְהַדָּגִים מַרְגִּישִׁים פָּחוֹת צַעַר. צַיִד לְשֵׁם סְפּוֹרְט אֵינוֹ רָאוּי, וּמוֹפָעִים אַכְזָרִיִּים – אֲסוּרִים.","פֶּרֶק ט״ו, הֲלָכוֹת ו׳, י״ב","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["לְמִשְׁפַּחַת לֵוִי יֵשׁ תֻּכִּי בִּכְלוּב, וְגַם כֶּלֶב שֶׁמִּסְתּוֹבֵב בֶּחָצֵר וּבָרְחוֹב. לְמִי חוֹבָה לָתֵת אֹכֶל לִפְנֵי שֶׁהֵם אוֹכְלִים?",["רַק לַכֶּלֶב, כִּי הוּא הַגָּדוֹל וְהֶחָשׁוּב שֶׁבָּהֶם","לַתֻּכִּי, כִּי אֵינוֹ יָכוֹל לִמְצֹא אֹכֶל לְבַד","לְאַף אֶחָד, כִּי הַחוֹבָה הִיא רַק בִּבְהֵמוֹת שֶׁבַּשָּׂדֶה","לִשְׁנֵיהֶם בְּדִיּוּק בְּאוֹתָהּ מִדָּה, בְּלִי שׁוּם הֶבְדֵּל"],1,"הַחוֹבָה הִיא בְּעִקָּר כְּלַפֵּי בַּעֲלֵי חַיִּים שֶׁתְּלוּיִים בָּנוּ לְגַמְרֵי. כֶּלֶב שֶׁמִּסְתּוֹבֵב בַּחוּץ יָכוֹל לְהִסְתַּדֵּר בִּשְׁעַת הַדְּחָק – וּבְכָל זֹאת מִדַּת חֲסִידוּת לְהַקְדִּים גַּם אוֹתוֹ.","פֶּרֶק ט״ו, הֲלָכָה ד׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["לְסָבָא יֵשׁ לוּל תַּרְנְגוֹלוֹת בֶּחָצֵר, וְתַרְנְגֹלֶת אַחַת דּוֹגֶרֶת עַל בֵּיצִים. מָה הַדִּין?",["חוֹבָה לְשַׁלֵּחַ אוֹתָהּ קֹדֶם, כְּמוֹ בְּכָל צִפּוֹר כְּשֵׁרָה","אָסוּר לָגַעַת בַּבֵּיצִים עַד שֶׁיִּבָּקְעוּ מֵהֶן אֶפְרוֹחִים","מֻתָּר לְסָבָא לָקַחַת אוֹתָן, כִּי הֵן שֶׁלּוֹ","מֻתָּר לָקַחַת רַק אִם מְשַׁלְּמִים לְמִישֶׁהוּ עֲלֵיהֶן"],2,"שִׁלּוּחַ הַקֵּן נוֹהֵג רַק בְּצִפּוֹר בָּר שֶׁאֵינָהּ שַׁיֶּכֶת לְאָדָם. הַתַּרְנְגוֹלוֹת שֶׁל סָבָא וּבֵיצֵיהֶן שֶׁלּוֹ, וּמֻתָּר לוֹ לָקַחַת כְּשֶׁיִּרְצֶה.","פֶּרֶק ט״ז, הֲלָכָה א׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["מָה לָמְדוּ חֲכָמִים מִסִּפּוּר \"קִבְרוֹת הַתַּאֲוָה\" עַל אֲכִילַת בָּשָׂר?",["שֶׁאָסוּר לֶאֱכֹל בָּשָׂר בְּכָל יְמוֹת הַשָּׁבוּעַ הָרְגִילִים","לֶאֱכֹל בָּשָׂר רַק כְּשֶׁרוֹצִים, וּבְלִי לְבַזְבֵּז כֶּסֶף","שֶׁבְּשַׂר עוֹף מֻתָּר, וּבְשַׂר בְּהֵמָה אָסוּר לְגַמְרֵי","לֶאֱכֹל כַּמָּה שֶׁיּוֹתֵר בָּשָׂר, כְּדֵי לִהְיוֹת חֲזָקִים"],1,"הַתַּאֲוָה הַמֻּפְרֶזֶת לְבָשָׂר מְסֻכֶּנֶת. לָכֵן אוֹכְלִים בָּשָׂר לְתֵאָבוֹן – כְּשֶׁבֶּאֱמֶת רוֹצִים – וּמוֹצִיאִים עַל מוֹתָרוֹת רַק מְעַט מִן הַכֶּסֶף.","פֶּרֶק י״ד, הֲלָכָה ה׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["לָמָּה צִוְּתָה הַתּוֹרָה מִצְווֹת כְּמוֹ אִסּוּר אֵבֶר מִן הַחַי, וְאִסּוּר לִשְׁחֹט בְּהֵמָה וּבְנָהּ בְּיוֹם אֶחָד?",["כְּדֵי שֶׁהַבָּשָׂר יִהְיֶה טָעִים יוֹתֵר וּבָרִיא יוֹתֵר","כְּדֵי שֶׁלֹּא נִתְרַגֵּל לְאַכְזָרִיּוּת כְּלַפֵּי בַּעֲלֵי הַחַיִּים","כְּדֵי לְהַרְבּוֹת בָּשָׂר לִכְבוֹד שַׁבָּת וְיוֹם טוֹב","כְּדֵי שֶׁיִּשָּׁאֲרוּ מַסְפִּיק בְּהֵמוֹת לַעֲבוֹדָה בַּשָּׂדֶה וּבַבַּיִת"],1,"הַתּוֹרָה הִתִּירָה לֶאֱכֹל בָּשָׂר, אֲבָל בְּכַמָּה מִצְווֹת הִדְרִיכָה אוֹתָנוּ לְרַחֵם. כָּךְ לֹא נִדַּרְדֵּר לְאַכְזָרִיּוּת וְלַאֲטִימוּת כְּלַפֵּי צַעֲרָם שֶׁל בַּעֲלֵי הַחַיִּים.","פֶּרֶק י״ד, הֲלָכָה ו׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["לְדָנִי יֵשׁ גּוּר כְּלָבִים, וְחָבֵר מַצִּיעַ לַחְתֹּךְ לַגּוּר אֶת הַזָּנָב כְּדֵי שֶׁיֵּרָאֶה יָפֶה. מָה נָכוֹן?",["אָסוּר מִן הַתּוֹרָה, כְּמוֹ מִי שֶׁמַּכֶּה כֶּלֶב מִתּוֹךְ כַּעַס","מֻתָּר מֵעִקַּר הַדִּין, אֲבָל עָדִיף לְרַחֵם וְלֹא לְצַעֵר אוֹתוֹ","מִצְוָה לַעֲשׂוֹת זֹאת, כְּדֵי שֶׁהַכֶּלֶב יִהְיֶה נָאֶה וּמְכֻבָּד","מֻתָּר רַק כְּשֶׁהַגּוּר יָשֵׁן וְאֵינוֹ מַרְגִּישׁ כְּלוּם"],1,"חִתּוּךְ כָּזֶה נַעֲשֶׂה לְתוֹעֶלֶת הָאָדָם וְלֹא מִתּוֹךְ אַכְזָרִיּוּת, וְלָכֵן מֵעִקַּר הַדִּין הוּא מֻתָּר. אֲבָל מִדַּת הָרַחֲמָנוּת אוֹמֶרֶת: אִם אֶפְשָׁר – לֹא מְצַעֲרִים.","פֶּרֶק ט״ו, הֲלָכָה ח׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["סָבָא קָנָה עוֹף שָׁלֵם לְשַׁבָּת, וְדָנִי שׁוֹאֵל: הַאִם צָרִיךְ לְהוֹצִיא מִמֶּנּוּ אֶת גִּיד הַנָּשֶׁה?",["כֵּן, כִּי גִּיד הַנָּשֶׁה אָסוּר בְּכָל בַּעֲלֵי הַחַיִּים","לֹא, כִּי בְּעוֹפוֹת גִּיד הַנָּשֶׁה מֻתָּר בַּאֲכִילָה","כֵּן, אֲבָל רַק אִם מְבַשְּׁלִים אֶת הָעוֹף לְשַׁבָּת","לֹא, כִּי אָסוּר לְמִי שֶׁאֵינוֹ קַצָּב לָגַעַת בַּגִּיד"],1,"גִּיד הַנָּשֶׁה אָסוּר בִּבְהֵמוֹת וְחַיּוֹת, וּמֻתָּר בְּעוֹפוֹת. כִּי הַתּוֹרָה אָסְרָה אֶת הַגִּיד ״אֲשֶׁר עַל כַּף הַיָּרֵךְ״, וְלָעוֹף אֵין כַּף יָרֵךְ עֲגֻלָּה – הַבָּשָׂר עַל יְרֵכוֹ שָׁטוּחַ.","פֶּרֶק כ״א, הֲלָכָה ד׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["בְּשִׁעוּר מַדָּעִים הִצִּיעוּ לִבְדֹּק בְּאֵיזֶה חֹם נְמָלִים מֵתוֹת. מָה עָדִיף לְפִי הַהֲלָכָה?",["לִבְחֹר נִסּוּי אַחֵר, שֶׁאֵינוֹ מְצַעֵר בַּעֲלֵי חַיִּים","לַעֲשׂוֹת אֶת הַנִּסּוּי דַּוְקָא בְּקוֹפִים, כִּי הֵם דּוֹמִים לָנוּ","לְהַחֲלִיף אֶת הַנְּמָלִים בְּצִפּוֹרִים קְטַנּוֹת, שֶׁקַּל לִרְאוֹת אוֹתָן","לְבַטֵּל אֶת כָּל שִׁעוּרֵי הַמַּדָּעִים, כִּי מַדָּע אָסוּר"],0,"מִן הַדִּין מֻתָּר לְתַלְמִידִים לַעֲרֹךְ נִסּוּיִים בַּחֲרָקִים. אֲבָל כֵּיוָן שֶׁאֵין בַּנִּסּוּי הַזֶּה תּוֹעֶלֶת מַדָּעִית מַמָּשִׁית, עָדִיף שֶׁיַּעַרְכוּ נִסּוּיִים שֶׁאֵינָם מְצַעֲרִים בַּעֲלֵי חַיִּים, כִּי רָאוּי לְרַחֵם עַל כָּל הַבְּרִיּוֹת.","פֶּרֶק ט״ו, הֲלָכָה י׳","בַּעֲלֵי חַיִּים בְּרַחֲמִים"],["אוֹרִי נָשַׁךְ פְּרוּסַת לֶחֶם, וְרָאָה עָלֶיהָ מְעַט דָּם מִן הַחֲנִיכַיִם. מָה הוּא עוֹשֶׂה?",["זוֹרֵק אֶת כָּל הַפְּרוּסָה, כִּי הִיא נֶאֶסְרָה לְגַמְרֵי","מְגָרֵד אֶת הַדָּם מִן הַלֶּחֶם, וּמַמְשִׁיךְ לֶאֱכֹל","מַמְשִׁיךְ לֶאֱכֹל כָּרָגִיל, כִּי דַּם אָדָם מֻתָּר לְגַמְרֵי","מְחַכֶּה שֵׁשׁ שָׁעוֹת, וְרַק אַחַר כָּךְ אוֹכֵל שׁוּב"],1,"חֲכָמִים אָסְרוּ דַּם אָדָם מִשּׁוּם מַרְאִית עַיִן. לָכֵן מְגָרְדִים אֶת הַדָּם שֶׁעַל הַלֶּחֶם, וְהַשְּׁאָר מֻתָּר. דָּם שֶׁבֵּין הַשִּׁנַּיִם – מֻתָּר לִמְצֹץ.","פֶּרֶק כ״ב, הֲלָכָה י״ד","בּוֹדְקִים וְנִזְהָרִים"],["זְבוּב נָפַל לְסִיר גָּדוֹל שֶׁל מְרַק עוֹף צָלוּל, וְלֹא מָצְאוּ אוֹתוֹ. מָה הַדִּין?",["הַזְּבוּב בָּטֵל בְּשִׁשִּׁים, וְאוֹכְלִים אֶת הַמָּרָק כָּרָגִיל","מְסַנְּנִים אֶת הַמָּרָק בְּמִסְנֶנֶת, וְהַמָּרָק הַמְסֻנָּן מֻתָּר","צָרִיךְ לִזְרֹק אֶת כָּל הַמָּרָק, וְאֵין לוֹ שׁוּם תַּקָּנָה","מַרְתִּיחִים שׁוּב אֶת הַמָּרָק, עַד שֶׁהַזְּבוּב נִמַּס בּוֹ"],1,"זְבוּב שָׁלֵם הוּא בְּרִיָּה, וְאֵינוֹ בָּטֵל. אֲבָל מָרָק צָלוּל אֶפְשָׁר לְסַנֵּן בְּמִסְנֶנֶת שֶׁזְּבוּב אֵינוֹ עוֹבֵר בָּהּ, וְהַמָּרָק מֻתָּר.","פֶּרֶק כ״ג, הֲלָכָה ד׳","בּוֹדְקִים וְנִזְהָרִים"],["אֵילוּ חֲרָקִים הַכֹּל מַסְכִּימִים שֶׁאֵין צֹרֶךְ לְחַפֵּשׂ אוֹתָם?",["חֲרָקִים שֶׁעֵין הָאָדָם אֵינָהּ יְכוֹלָה לִרְאוֹת כְּלָל","חֲרָקִים יְרֻקִּים, כִּי הֵם דּוֹמִים לְצֶבַע הֶעָלֶה","כָּל חֶרֶק שֶׁקָּטָן יוֹתֵר מִגַּרְגַּר אֹרֶז אוֹ חִטָּה","חֲרָקִים שֶׁמּוֹצְאִים רַק אַחֲרֵי שֶׁהַמַּאֲכָל כְּבָר בֻּשַּׁל"],0,"הַתּוֹרָה נִתְּנָה לְפִי רְאִיַּת הָאָדָם, וּמָה שֶׁאִי אֶפְשָׁר לִרְאוֹת – אֵין צֹרֶךְ לְחַפֵּשׂ. עַל חֲרָקִים שֶׁקָּשֶׁה מְאוֹד לִרְאוֹת יֵשׁ מַחֲלֹקֶת, וְרַבָּנִים רַבִּים מוֹרִים לְהַחְמִיר וְלִבְדֹּק גַּם אוֹתָם.","פֶּרֶק כ״ג, הֲלָכוֹת ו׳–ז׳","בּוֹדְקִים וְנִזְהָרִים"],["בְּקֻפְסַת פֵּרוֹת, שֶׁבְּדֶרֶךְ כְּלָל אֵין בָּהֶם חֲרָקִים, מָצְאוּ שְׁלֹשָׁה חֲרָקִים. מָה עַכְשָׁו?",["זוֹרְקִים רַק אֶת הַפֵּרוֹת שֶׁבָּהֶם נִמְצְאוּ הַחֲרָקִים","מַמְשִׁיכִים לֶאֱכֹל בְּלִי בְּדִיקָה, כִּי הוֹלְכִים אַחַר הָרֹב","כָּל הַפֵּרוֹת שֶׁבַּקֻּפְסָה צְרִיכִים מֵעַכְשָׁו בְּדִיקָה","מַחְזִירִים אֶת הַקֻּפְסָה, כִּי אָסוּר לִבְדֹּק בְּעַצְמְךָ"],2,"מַאֲכָל שֶׁנֶּחְשָׁב נָקִי, וְנִמְצְאוּ בּוֹ שְׁלֹשָׁה חֲרָקִים – כָּל מָה שֶׁבְּאוֹתָהּ אֲרִיזָה נֶחְשָׁב עַכְשָׁו כְּמַאֲכָל שֶׁיֵּשׁ בּוֹ חֲרָקִים, וְאָסוּר לְאָכְלוֹ בְּלִי בְּדִיקָה.","פֶּרֶק כ״ג, הֲלָכָה ה׳","בּוֹדְקִים וְנִזְהָרִים"],["לָמָּה אָסוּר לְבַשֵּׁל בָּשָׂר שֶׁלֹּא הֻכְשַׁר?",["כִּי הַדָּם יוֹצֵא בַּבִּשּׁוּל וְחוֹזֵר לְהִבָּלַע בּוֹ","כִּי בָּשָׂר שֶׁלֹּא נִמְלַח אֵינוֹ טָעִים לַאֲכִילָה","כִּי הַמֶּלַח שׁוֹמֵר עַל הַבָּשָׂר שֶׁלֹּא יִתְקַלְקֵל","כִּי כָּךְ נָהֲגוּ הַקַּצָּבִים, וְאֵין לָזֶה טַעַם"],0,"דָּם שֶׁבָּלוּעַ בַּבָּשָׂר כְּדֶרֶךְ טִבְעוֹ – מֻתָּר. אֲבָל בַּבִּשּׁוּל הַדָּם יוֹצֵא וְנִבְלָע שׁוּב, וְכָל הַבָּשָׂר נֶאֱסָר. לָכֵן מוֹלְחִים אוֹ צוֹלִים קֹדֶם.","פֶּרֶק כ״ב, הֲלָכָה ב׳","בּוֹדְקִים וְנִזְהָרִים"],["בְּתוֹךְ תַּפּוּחַ קָטוּף הִתְפַּתְּחָה תּוֹלַעַת. מֵאֵימָתַי חָל עָלֶיהָ אִסּוּר שֶׁרֶץ?",["מִן הָרֶגַע שֶׁהִתְחִילָה לִגְדֹּל בְּתוֹךְ הַפְּרִי","מִן הָרֶגַע שֶׁיָּצְאָה מִן הַתַּפּוּחַ הַחוּצָה","רַק אַחֲרֵי שֶׁהַתַּפּוּחַ הַנָּגוּעַ נִרְקַב לְגַמְרֵי","רַק כְּשֶׁיֵּשׁ יוֹתֵר מִשָּׁלֹשׁ תּוֹלָעִים בַּתַּפּוּחַ"],1,"חֶרֶק שֶׁגָּדַל בְּתוֹךְ פְּרִי קָטוּף נֶחְשָׁב חֵלֶק מִן הַפְּרִי. רַק כְּשֶׁיָּצָא וְהִתְחִיל לִשְׁרֹץ – הוּא נֶאֱסָר. וּבְכָל זֹאת, מָה שֶׁמְּעוֹרֵר גֹּעַל – לֹא אוֹכְלִים.","פֶּרֶק כ״ג, הֲלָכָה ג׳","בּוֹדְקִים וְנִזְהָרִים"],["סָבָא מְגַדֵּל תַּרְנְגוֹלוֹת יַחַד עִם תַּרְנְגוֹל, וּבְבֵיצָה מִן הַלּוּל שֶׁלּוֹ נִמְצָא כֶּתֶם דָּם. מָה עוֹשִׂים?",["מוֹצִיאִים רַק אֶת הַכֶּתֶם, וְאוֹכְלִים אֶת שְׁאָר הַבֵּיצָה","זוֹרְקִים אֶת כָּל הַבֵּיצָה, כִּי זוֹ בֵּיצָה מֻפְרֵית","מְבַשְּׁלִים אֶת הַבֵּיצָה הַרְבֵּה זְמַן, עַד שֶׁהַדָּם נֶעְלָם","זוֹרְקִים אֶת כָּל הַבֵּיצִים שֶׁבַּלּוּל שֶׁל סָבָא"],1,"בְּבֵיצָה מֻפְרֵית הַדָּם עָלוּל לִהְיוֹת תְּחִלַּת אֶפְרוֹחַ, וְנוֹהֲגִים לֶאֱסֹר אֶת כָּל הַבֵּיצָה. שְׁאָר הַבֵּיצִים – מֻתָּרוֹת.","פֶּרֶק כ״ד, הֲלָכָה ב׳","בּוֹדְקִים וְנִזְהָרִים"],["לָמָּה לְפִי הַדִּין אֵין חוֹבָה לִבְדֹּק בֵּיצִים עִם חוֹתֶמֶת?",["כִּי הֵן עוֹבְרוֹת בְּדִיקָה בַּמִּפְעָל לִפְנֵי שֶׁנִּמְכָּרוֹת","כִּי אֵינָן מֻפְרוֹת, וְלֹא יִתְפַּתֵּחַ מֵהֶן אֶפְרוֹחַ","כִּי בְּבֵיצֵי תַּרְנְגֹלֶת אַף פַּעַם אֵין דָּם","כִּי הַחוֹתֶמֶת עַצְמָהּ הִיא הַהֶכְשֵׁר שֶׁל הָרַבָּנוּת"],1,"הַדָּם הָאָסוּר הוּא רַק דָּם שֶׁמִּמֶּנּוּ מִתְרַקֵּם אֶפְרוֹחַ, וּבְבֵיצָה שֶׁאֵינָהּ מֻפְרֵית זֶה לֹא יָכוֹל לִקְרוֹת. וְאִם רוֹאִים בָּהּ דָּם – מוֹצִיאִים אוֹתוֹ מִשּׁוּם מַרְאִית עַיִן.","פֶּרֶק כ״ד, הֲלָכָה ג׳","בּוֹדְקִים וְנִזְהָרִים"],["אַבָּא מֵכִין עוֹף כָּשֵׁר לְשַׁבָּת, וְאָבִי רוֹאֶה בּוֹ נְקֻדָּה שֶׁל דָּם קָרוּשׁ מַמָּשׁ. מָה עוֹשִׂים?",["זוֹרְקִים אֶת כָּל הָעוֹף, כִּי נִמְצָא בּוֹ דָּם","חוֹתְכִים אֶת מְקוֹם הַדָּם וְזוֹרְקִים, וְאֶת הָעוֹף מְבַשְּׁלִים","מְבַשְּׁלִים אֶת הָעוֹף כְּמוֹ שֶׁהוּא, כִּי הוּא כְּבָר הֻכְשַׁר","מוֹלְחִים אֶת כָּל הָעוֹף שׁוּב, וּמַשְׁהִים אוֹתוֹ שָׁעָה"],1,"עוֹף שֶׁהֻכְשַׁר וּמָצְאוּ בּוֹ צְרִירוּת דָּם – חוֹתְכִים אֶת הַמָּקוֹם וְזוֹרְקִים, וְהַשְּׁאָר כָּשֵׁר. וְאִם טָעוּ וּבִשְּׁלוּ בְּלִי לַחְתֹּךְ – הָעוֹף כָּשֵׁר.","פֶּרֶק כ׳, הֲלָכָה ט״ז","בּוֹדְקִים וְנִזְהָרִים"],["אָבִי אָפָה עוּגָה, וְרַק אַחַר כָּךְ נִזְכַּר שֶׁשָּׁכַח לְנַפּוֹת אֶת הַקֶּמַח. מָה דִּין הָעוּגָה?",["הָעוּגָה כְּשֵׁרָה, כִּי עַל זֶה מַסְכִּימִים כָּל הַפּוֹסְקִים","הָעוּגָה אֲסוּרָה, כִּי אוּלַי נֶאֶפוּ בָּהּ שְׁרָצִים","צָרִיךְ לְפוֹרֵר אֶת הָעוּגָה וְלִבְדֹּק כָּל פֵּרוּר","הָעוּגָה מֻתֶּרֶת רַק לְמִי שֶׁלֹּא יוֹדֵעַ מָה קָרָה"],0,"נָהֲגוּ יִשְׂרָאֵל לְנַפּוֹת אֶת הַקֶּמַח לִפְנֵי הָאֲפִיָּה, וּלְהֲלָכָה מַסְפִּיקָה נָפָה רְגִילָה. אֲבָל מֻסְכָּם עַל הַכֹּל: אִם אָפוּ אוֹ בִּשְּׁלוּ קֶמַח שֶׁלֹּא נֻפָּה – הַמַּאֲפֶה אוֹ הַתַּבְשִׁיל כְּשֵׁרִים.","פֶּרֶק כ״ג, הֲלָכָה ט״ו","בּוֹדְקִים וְנִזְהָרִים"],["בְּטָעוּת הִתְבַּשְּׁלוּ קְצִיצוֹת בָּשָׂר בְּרֹטֶב שֶׁל שַׁמֶּנֶת. מָה עוֹשִׂים בַּתַּבְשִׁיל?",["נוֹתְנִים אוֹתוֹ לֶחָתוּל שֶׁבֶּחָצֵר, כְּדֵי שֶׁלֹּא יִתְבַּזְבֵּז","זוֹרְקִים אוֹתוֹ, כִּי אָסוּר גַּם לֵהָנוֹת מִמֶּנּוּ","מוֹכְרִים אוֹתוֹ בְּזוֹל לְשָׁכֵן גּוֹי שֶׁאוֹהֵב קְצִיצוֹת","נוֹתְנִים אוֹתוֹ בְּמַתָּנָה לְפוֹעֵל גּוֹי שֶׁעוֹבֵד בַּבַּיִת"],1,"בָּשָׂר וְחָלָב שֶׁהִתְבַּשְּׁלוּ – אֲסוּרִים בַּהֲנָאָה. גַּם מַתָּנָה לְגוֹי וְגַם אֹכֶל לְחַיּוֹת הֶפְקֵר נוֹתְנִים לָנוּ הֲנָאָה. לָכֵן קוֹבְרִים אוֹ זוֹרְקִים לַפַּח.","פֶּרֶק כ״ה, הֲלָכָה א׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אַבָּא עֵרֵב תַּבְשִׁיל בָּשָׂר רוֹתֵחַ, וּבְטָעוּת עֵרֵב בְּכַף מַתֶּכֶת חֲלָבִית נְקִיָּה. מָה הַדִּין?",["הַתַּבְשִׁיל אָסוּר, וְגַם הַכַּף צְרִיכָה לְהִזָּרֵק","הַתַּבְשִׁיל כָּשֵׁר, וְהַכַּף צְרִיכָה הַכְשָׁרָה בְּהַגְעָלָה","הַתַּבְשִׁיל כָּשֵׁר, וְהַכַּף נִשְׁאֶרֶת חֲלָבִית כְּמוֹ קֹדֶם","הַתַּבְשִׁיל אָסוּר, אֲבָל אֶת הַכַּף מַסְפִּיק לִשְׁטֹף בְּסַבּוֹן"],1,"כַּף מַתֶּכֶת נְקִיָּה אֵינָהּ מוֹסִיפָה טַעַם, וְלָכֵן בְּדִיעֲבַד הַתַּבְשִׁיל כָּשֵׁר. אֲבָל הַכַּף הָיְתָה פַּעַם בְּחָלָב רוֹתֵחַ וּפַעַם בְּבָשָׂר רוֹתֵחַ, וּצְרִיכָה הַגְעָלָה.","פֶּרֶק כ״ה, הֲלָכָה י״א","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בַּאֲרוּחַת בָּשָׂר אָכַל אֵיתָן רַק סָלָט, שֶׁלָּקְחוּ מִמֶּנּוּ בְּמַזְלְגוֹת בְּשָׂרִיִּים. מָתַי מֻתָּר לוֹ לֶאֱכֹל גְּבִינָה?",["רַק אַחֲרֵי שֶׁיַּמְתִּין כְּמוֹ אַחֲרֵי אֲכִילַת בָּשָׂר","מִיָּד, כִּי אֵין בַּסָּלָט טַעַם בָּשָׂר","רַק לְמָחֳרָת בַּבֹּקֶר, אַחֲרֵי שֶׁיִּישַׁן לַיְלָה שָׁלֵם","מֻתָּר לוֹ לֶאֱכֹל אֶת הַגְּבִינָה יַחַד עִם הַסָּלָט עַצְמוֹ"],1,"הַסָּלָט נֶחְשָׁב \"בְּחֶזְקַת בְּשָׂרִי\", וְלָכֵן לֹא אוֹכְלִים אוֹתוֹ עִם חָלָב. אֲבָל אֵין בּוֹ טַעַם בָּשָׂר, וּמִיָּד אַחֲרָיו מֻתָּר לֶאֱכֹל חָלָב.","פֶּרֶק כ״ו, הֲלָכָה ה׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בְּשַׁבָּת אָכַל יוֹנָתָן מִן הַחַמִּין רַק תַּפּוּחֵי אֲדָמָה, שֶׁהִתְבַּשְּׁלוּ עִם הַבָּשָׂר. מָה דִּינוֹ?",["יָכוֹל לֶאֱכֹל חָלָב מִיָּד, כִּי לֹא אָכַל בָּשָׂר","מַמְתִּין כְּמוֹ אַחֲרֵי בָּשָׂר, כִּי יֵשׁ בָּהֶם טַעְמוֹ","צָרִיךְ רַק לִשְׁטֹף אֶת הַיָּדַיִם, וְאָז אוֹכֵל חָלָב","מַמְתִּין חֲצִי זְמַן, כִּי זֶה רַק טַעַם וְלֹא בָּשָׂר"],1,"תַּבְשִׁיל שֶׁהִתְבַּשֵּׁל עִם בָּשָׂר – יֵשׁ בּוֹ טַעַם בָּשָׂר. לָכֵן נוֹהֲגִים לְהַמְתִּין אַחֲרָיו כְּמוֹ אַחֲרֵי בָּשָׂר עַצְמוֹ.","פֶּרֶק כ״ו, הֲלָכָה ה׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בַּבַּיִת יֵשׁ מִיקְרוֹגַל אֶחָד, וְרוֹצִים לְחַמֵּם בּוֹ קְצִיצוֹת עוֹף. אֵיךְ עוֹשִׂים זֹאת?",["מַנִּיחִים אֶת הַקְּצִיצוֹת יָשָׁר עַל הַצַּלַּחַת הַקְּבוּעָה שֶׁל הַמִּיקְרוֹגַל","עַל צַלַּחַת בְּשָׂרִית, וּמְכַסִּים בְּמִכְסֶה בְּשָׂרִי מְיֻחָד","אָסוּר לְחַמֵּם בָּשָׂר בְּמִיקְרוֹגַל שֶׁחִמְּמוּ בּוֹ חָלָב","מְחַמְּמִים בְּלִי כִּסּוּי, כְּדֵי שֶׁהָאֵדִים יֵצְאוּ הַחוּצָה"],1,"בְּאוֹתוֹ מִיקְרוֹגַל אֶפְשָׁר לְחַמֵּם בָּשָׂר וְחָלָב, אִם מַפְרִידִים: צַלַּחַת מֵאוֹתוֹ סוּג, וּמִכְסֶה מְיֻחָד לְכָל סוּג – כְּדֵי שֶׁלֹּא יִכָּנְסוּ אֵדִים רַבִּים לָאֹכֶל.","פֶּרֶק כ״ה, הֲלָכָה ט״ו","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["אַחֲרֵי שֶׁעָבַר זְמַן הַהַמְתָּנָה, מָצָא אֵלִיָּה חֲתִיכַת בָּשָׂר קְטַנָּה בֵּין שִׁנָּיו. מָה הוּא עוֹשֶׂה?",["מוֹצִיא אוֹתָהּ, מְנַקֶּה אֶת הַפֶּה, וְאוֹכֵל חָלָב","מַתְחִיל לְהַמְתִּין שׁוּב מִן הַהַתְחָלָה לִפְנֵי הֶחָלָב","אוֹכֵל חָלָב מִיָּד, בְּלִי לְהוֹצִיא אֶת הַחֲתִיכָה","בּוֹלֵעַ אוֹתָהּ, וְאָסוּר לוֹ לֶאֱכֹל חָלָב כָּל הַיּוֹם"],0,"מוֹצִיאִים אֶת הַבָּשָׂר מִן הַפֶּה, מְנַקִּים אֶת הַפֶּה – בְּמַאֲכָל מוּצָק וּשְׁתִיָּה אוֹ בְּצִחְצוּחַ שִׁנַּיִם – וּמִיָּד מֻתָּר לֶאֱכֹל חָלָב. אֵין צֹרֶךְ לְהַתְחִיל לְהַמְתִּין שׁוּב.","פֶּרֶק כ״ו, הֲלָכָה ד׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["לָמָּה לֹא מְחַיְּבִים יֶלֶד בֶּן חָמֵשׁ לְהַמְתִּין זְמַן אָרֹךְ כְּמוֹ אָבִיו?",["כִּי לְיֶלֶד קָטָן אֵין שׁוּם מִצְוַת חִנּוּךְ בְּכַשְׁרוּת","כִּי אֵין מְחַנְּכִים בְּדֶרֶךְ שֶׁמְּצַעֶרֶת אוֹ פּוֹגַעַת בִּבְרִיאוּת","כִּי טַעַם הַבָּשָׂר אֵינוֹ נִשְׁאָר בַּפֶּה שֶׁל יְלָדִים","כִּי לִילָדִים מֻתָּר לֶאֱכֹל בָּשָׂר וְחָלָב גַּם יַחַד"],1,"מִצְוָה לְחַנֵּךְ, אֲבָל חִנּוּךְ טוֹב הוּא בְּהַדְרָגָה וּבְלִי צַעַר. לָכֵן מַתְחִילִים בְּהַמְתָּנָה קְצָרָה, וּמַאֲרִיכִים כְּכָל שֶׁהַיֶּלֶד גָּדֵל.","פֶּרֶק כ״ו, הֲלָכָה ז׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בַּאֲרוּחַת בָּשָׂר נִשְׁאֲרָה פְּרוּסַת לֶחֶם, שֶׁנָּגְעוּ בָּהּ בְּיָדַיִם שְׁמֵנוֹת מִן הָעוֹף. מָה הַדִּין?",["לֹא מַגִּישִׁים בַּאֲרוּחָה חֲלָבִית, שֶׁמָּא דָּבַק בָּהּ בָּשָׂר","מַגִּישִׁים אוֹתָהּ בַּאֲרוּחָה חֲלָבִית, כִּי לֶחֶם הוּא תָּמִיד פַּרְוֶה","הִיא אֲסוּרָה בַּאֲכִילָה לְגַמְרֵי, וְזוֹרְקִים אוֹתָהּ מִיָּד לַפַּח","מֻתָּר לֶאֱכֹל אוֹתָהּ רַק עִם גְּבִינָה, וְלֹא לְבַד"],0,"לֶחֶם שֶׁנָּגְעוּ בּוֹ בְּיָדַיִם שְׁמֵנוֹת מִבָּשָׂר – לֹא מַגִּישִׁים בַּאֲרוּחָה חֲלָבִית, שֶׁמָּא יֹאכְלוּ שְׁיָרֵי בָּשָׂר עִם חָלָב. אִם נִזְהֲרוּ שֶׁלֹּא לָגַעַת בּוֹ – מֻתָּר.","פֶּרֶק כ״ה, הֲלָכָה ו׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["נֹעָה מְכִינָה סָלַט יְרָקוֹת בִּקְעָרָה בְּשָׂרִית. בְּאֵיזוֹ כַּף נָכוֹן לְעָרְבֵּב אוֹתוֹ?",["בְּכַף חֲלָבִית, כִּי הַסָּלָט פַּרְוֶה וְכָל כַּף מַתְאִימָה לוֹ","בְּכַף בְּשָׂרִית, כְּדֵי לִשְׁמֹר עַל הַהַפְרָדָה בֵּין הַכֵּלִים","רַק בְּכַף חַד פַּעֲמִית, כִּי אָסוּר לְעָרְבֵּב כֵּלִים לְעוֹלָם","בְּכַף חֲלָבִית, כְּדֵי שֶׁאֶפְשָׁר יִהְיֶה לֶאֱכֹל אוֹתוֹ עִם גְּבִינָה"],1,"גַּם מַאֲכָל פַּרְוֶה קַר מְכִינִים בְּכֵלִים מִמִּין אֶחָד: קְעָרָה בְּשָׂרִית – כַּף בְּשָׂרִית. רַק בִּשְׁעַת הַצֹּרֶךְ, כְּשֶׁאֵין כַּף בְּשָׂרִית שְׁטוּפָה, אֶפְשָׁר לְעָרְבֵּב בְּכַף חֲלָבִית.","פֶּרֶק כ״ה, הֲלָכָה ט׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בְּקֻפְסַת הָאֹכֶל שֶׁל עִידוֹ נָגְעָה פְּרוּסַת לֶחֶם בַּנַּקְנִיק הַלַּח. עַכְשָׁו הוּא רוֹצֶה לִמְרֹחַ עָלֶיהָ גְּבִינָה. מָה יַעֲשֶׂה?",["זוֹרֵק אֶת כָּל הַפְּרוּסָה, כִּי הִיא נַעֲשְׂתָה בְּשָׂרִית לְגַמְרֵי","מְגָרֵד מִן הַלֶּחֶם אֶת הַמָּקוֹם שֶׁנָּגַע בַּנַּקְנִיק","שׁוֹטֵף אֶת הַפְּרוּסָה בְּמַיִם, וְאַחַר כָּךְ מוֹרֵחַ גְּבִינָה","מוֹרֵחַ גְּבִינָה כָּרָגִיל, כִּי לֶחֶם הוּא תָּמִיד פַּרְוֶה"],1,"לֶחֶם שֶׁנָּגַע בְּבָשָׂר לַח – מֻתָּר לֶאֱכֹל עִם בָּשָׂר. וְאִם רוֹצִים לֶאֱכֹל אוֹתוֹ עִם חָלָב, מְגָרְדִים מִן הַלֶּחֶם אֶת מָה שֶׁנָּגַע בַּבָּשָׂר, כִּי אִי אֶפְשָׁר לִשְׁטֹף אֶת הַלֶּחֶם.","פֶּרֶק ל״ה, הֲלָכָה א׳","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["נֹעָה רוֹצָה לַחְתֹּךְ מְלָפְפוֹן לְסָלָט, שֶׁיֹּאכְלוּ אוֹתוֹ עִם פַּשְׁטִידַת גְּבִינָה. עַל אֵיזֶה קֶרֶשׁ נָכוֹן לַחְתֹּךְ?",["עַל הַקֶּרֶשׁ הַבְּשָׂרִי, כִּי מְלָפְפוֹן הוּא פַּרְוֶה וְאֵינוֹ סוֹפֵג","עַל קֶרֶשׁ חֲלָבִי אוֹ פַּרְוֶה, כִּי קֶרֶשׁ סוֹפֵג טְעָמִים","עַל כָּל קֶרֶשׁ, אִם שׁוֹטְפִים אֶת הַמְּלָפְפוֹן אַחֲרֵי הַחִתּוּךְ","רַק עַל צַלַּחַת חַד פַּעֲמִית, כִּי קְרָשִׁים אֲסוּרִים לְסָלָט"],1,"קֶרֶשׁ חִתּוּךְ מֵעֵץ אוֹ מִפְּלַסְטִיק סוֹפֵג טְעָמִים, וְלָכֵן מְיַחֲדִים קֶרֶשׁ לִבְשָׂרִי, קֶרֶשׁ לַחֲלָבִי, וּמִי שֶׁצָּרִיךְ – גַּם קֶרֶשׁ לְפַרְוֶה. אֲבָל בְּדִיעֲבַד, יְרָקוֹת שֶׁנֶּחְתְּכוּ עַל קֶרֶשׁ בְּשָׂרִי נָקִי וְעֹרְבוּ בְּמַאֲכָל חֲלָבִי – הַמַּאֲכָל כָּשֵׁר.","פֶּרֶק ל״ב, הֲלָכָה י״ג","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["בִּזְמַן הַבִּשּׁוּל נָפְלָה קְצִיצָה מִן הַמַּחֲבַת עַל מִשְׁטַח הַמַּתֶּכֶת שֶׁמִּתַּחַת לַחֲצוּבָה. מָה הַדִּין?",["אוֹכְלִים אוֹתָהּ, כִּי הָאֵשׁ שׂוֹרֶפֶת כָּל מָה שֶׁנִּשְׁפַּךְ שָׁם","לֹא אוֹכְלִים, אֶלָּא אִם יָדוּעַ שֶׁהַמִּשְׁטָח נֻקָּה וְעוֹדֶנּוּ נָקִי","אוֹכְלִים אוֹתָהּ, אִם שׁוֹטְפִים אוֹתָהּ קֹדֶם בְּמַיִם חַמִּים","זוֹרְקִים אֶת הַקְּצִיצָה וְגַם אֶת כָּל הַקְּצִיצוֹת שֶׁבַּמַּחֲבַת"],1,"מַחְמִירִים שֶׁלֹּא לֶאֱכֹל מַאֲכָל שֶׁנָּפַל עַל הַמִּשְׁטָח שֶׁמִּתַּחַת לַחֲצוּבָה, כִּי לִפְעָמִים יֵשׁ שָׁם שְׁיָרִים בְּשָׂרִיִּים וַחֲלָבִיִּים. אֲבָל אִם יָדוּעַ שֶׁנִּקּוּ אֶת הַמִּשְׁטָח הֵיטֵב וְהוּא עֲדַיִן נָקִי – מֻתָּר לֶאֱכֹל.","פֶּרֶק כ״ה, הֲלָכָה י״ג","בָּשָׂר לְחוּד וְחָלָב לְחוּד"],["עֵץ לִימוֹן בֶּחָצֵר מַסְתִּיר אֶת הָאוֹר בְּחַלּוֹן הַחֶדֶר. מָה נָכוֹן לַעֲשׂוֹת?",["לַעֲקֹר אֶת הָעֵץ מִיָּד, כִּי הוּא מַזִּיק לַבַּיִת","לְקַצֵּץ אֶת הָעֲנָפִים שֶׁמַּסְתִּירִים, גַּם אִם צָרִיךְ לַחֲזֹר","לְהַשְׁאִיר אוֹתוֹ, כִּי אָסוּר לָגַעַת בְּעֵץ פְּרִי","לַעֲקֹר אוֹתוֹ, רַק אִם הַפֵּרוֹת שֶׁלּוֹ לֹא טְעִימִים"],1,"הַסְתָּרַת הַחַלּוֹן הִיא נֵזֶק, אֲבָל כְּשֶׁאֶפְשָׁר לְתַקֵּן בְּקִצּוּץ הָעֲנָפִים – לֹא עוֹקְרִים, גַּם אִם זֶה טֹרַח. וּמֻתָּר לִגְזֹם עֲנָפִים, כִּי הָעֵץ נִשְׁאָר בָּרִיא.","פֶּרֶק י״ג, הֲלָכוֹת ג׳, ה׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["הַתּוֹרָה אָסְרָה עַל חַיָּלִים לִכְרֹת עֲצֵי פְּרִי בְּמִלְחָמָה. מָה לוֹמְדִים מִזֶּה לִימֵי שָׁלוֹם?",["שֶׁבִּימֵי שָׁלוֹם מֻתָּר לִכְרֹת, כִּי אֵין סַכָּנָה","שֶׁהָאִסּוּר חָל רַק עַל חַיָּלִים, וְלֹא עַל אֲחֵרִים","שֶׁכָּל שֶׁכֵּן אָסוּר לְהַשְׁחִית דְּבָרִים מוֹעִילִים","שֶׁאָסוּר לִכְרֹת רַק עֵצִים שֶׁל אוֹיְבִים, בִּזְמַן מָצוֹר"],2,"אִם אֲפִלּוּ בְּסַעֲרַת הַמִּלְחָמָה אָסוּר לְהַשְׁחִית – קַל וָחֹמֶר בִּימֵי שָׁלוֹם. מִכָּאן נִלְמָד הָאִסּוּר לְהַשְׁחִית כֵּלִים, בְּגָדִים, אֹכֶל וְטֶבַע.","פֶּרֶק י״ג, הֲלָכוֹת ב׳, ז׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בְּאֶרֶץ יִשְׂרָאֵל יֵשׁ מַאֲפִיָּה שֶׁל גּוֹי, וְכָל הָעוֹבְדִים בָּהּ גּוֹיִם. הַחֳמָרִים כְּשֵׁרִים. מָה הַדִּין בַּלֶּחֶם?",["מֻתָּר, כִּי כָּל הַחֳמָרִים בַּלֶּחֶם כְּשֵׁרִים לְגַמְרֵי","אָסוּר, כִּי בָּאָרֶץ יֵשׁ מַאֲפִיּוֹת שֶׁל יְהוּדִים","מֻתָּר, אֲבָל רַק עוּגוֹת וְלֹא לַחְמָנִיּוֹת וְכִכָּרוֹת","אָסוּר, אֲבָל לַחְמָנִיּוֹת קְטַנּוֹת מֻתָּרוֹת לִילָדִים"],1,"חֲכָמִים אָסְרוּ פַּת גּוֹיִם כְּדֵי לִמְנֹעַ הִתְבּוֹלְלוּת, וְדִין עוּגוֹת כְּדִין לֶחֶם. בְּחוּץ לָאָרֶץ, כְּשֶׁאֵין לֶחֶם שֶׁל יְהוּדִים, הִתִּירוּ מִפְּנֵי הַדֹּחַק – אֲבָל בָּאָרֶץ אֵין הֶתֵּר. וְאִם יְהוּדִי הִדְלִיק אֶת הַתַּנּוּר – הַלֶּחֶם מֻתָּר.","פֶּרֶק כ״ח, הֲלָכוֹת א׳–ג׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["טַבָּח גּוֹי בִּשֵּׁל בְּמִטְבָּח כָּשֵׁר כַּמָּה מַאֲכָלִים, בְּלִי שׁוּם עֶזְרָה שֶׁל יְהוּדִי. מַה מֻּתָּר לֶאֱכֹל?",["אֹרֶז מְבֻשָּׁל, כִּי אֹרֶז אֵינוֹ מִסּוּג הַדָּגָן","רִיבַּת פֵּרוֹת, כִּי פֵּרוֹת נֶאֱכָלִים גַּם כְּשֶׁהֵם חַיִּים","חֲבִיתָה, כִּי אֶפְשָׁר לִגְמֹעַ בֵּיצָה גַּם חַיָּה","קְצִיצוֹת בָּשָׂר, כִּי הַבָּשָׂר עַצְמוֹ נִקְנָה בְּהֶכְשֵׁר טוֹב"],1,"בִּשּׁוּלֵי גּוֹיִם אֲסוּרִים רַק בְּמַאֲכָל שֶׁאֵינוֹ נֶאֱכָל חַי. פֵּרוֹת אוֹכְלִים חַיִּים – וְלָכֵן הָרִיבָּה מֻתֶּרֶת. בֵּיצָה גּוֹמְעִים רַק בִּשְׁעַת הַדְּחָק, וְלָכֵן הִיא כְּמַאֲכָל שֶׁאֵינוֹ נֶאֱכָל חַי.","פֶּרֶק כ״ח, הֲלָכוֹת ה׳–ו׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["אַבָּא שֶׁל נֹעַם הִגִּיעַ לַמִּקְוֶה עִם מַחֲבַת חֲדָשָׁה מִמַּתֶּכֶת. מָה צָרִיךְ לַעֲשׂוֹת?",["לְהָסִיר אֶת מַדְבֵּקַת הַמְּחִיר, וּלְהַכְנִיס הַכֹּל בְּבַת אַחַת","לְהַשְׁאִיר אֶת הַמַּדְבֵּקָה, וּלְהַחֲזִיק חָזָק בַּיָּדִית כָּל הַזְּמַן","לִטְבֹּל קֹדֶם חֲצִי מַחֲבַת, וְאַחַר כָּךְ אֶת הַחֲצִי הַשֵּׁנִי","לְהָסִיר אֶת הַמַּדְבֵּקָה, וּלְהַשְׁאִיר אֶת הַיָּדִית מִחוּץ לַמַּיִם"],0,"מַדְבֵּקָה שֶׁמְּסִירִים לִפְנֵי הַשִּׁמּוּשׁ חוֹצֶצֶת, וְהַכְּלִי כֻּלּוֹ – גַּם הַיָּדִית – צָרִיךְ לִהְיוֹת בַּמַּיִם בְּבַת אַחַת. וּמַרְפִּים לְרֶגַע מֵהַכְּלִי, כְּדֵי שֶׁהַיָּד לֹא תַּחֲצֹץ.","פֶּרֶק ל״א, הֲלָכָה ד׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["יוֹסֵף בֶּן תֵּשַׁע רוֹצֶה לִטְבֹּל לְבַד אֶת הַכֵּלִים הַחֲדָשִׁים שֶׁל הַמִּשְׁפָּחָה. מָה נָכוֹן?",["יֶלֶד אֵינוֹ רַשַּׁאי לִטְבֹּל, רַק גָּדוֹל יָכוֹל","יָכוֹל לִטְבֹּל וּלְבָרֵךְ, וְגָדוֹל צָרִיךְ לִרְאוֹת וּלְהָעִיד","יָכוֹל לִטְבֹּל, אֲבָל אָסוּר לוֹ לְבָרֵךְ אֶת הַבְּרָכָה","יָכוֹל לִטְבֹּל לְבַד, וְאַחַר כָּךְ פָּשׁוּט לְסַפֵּר בַּבַּיִת"],1,"קָטָן רַשַּׁאי לִטְבֹּל וּלְבָרֵךְ, אֲבָל אֵינוֹ יָכוֹל לְהָעִיד שֶׁהַטְּבִילָה נַעֲשְׂתָה כַּהֲלָכָה. לָכֵן צָרִיךְ גָּדוֹל שֶׁיִּרְאֶה, וְאִם לֹא הָיָה גָּדוֹל – טוֹבְלִים שׁוּב.","פֶּרֶק ל״א, הֲלָכָה ה׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בְּכָל יוֹם אוֹכֵל אֵלִי הַרְבֵּה חֲטִיפִים וּמַמְתַּקִּים. מָה אוֹמֶרֶת עַל כָּךְ הַהֲלָכָה?",["זֶה עִנְיָן שֶׁל טַעַם בִּלְבַד, וְאֵין בּוֹ שׁוּם מִצְוָה","שְׁמִירַת הַבְּרִיאוּת הִיא מִצְוָה, וּמְמַעֲטִים בְּמַה שֶּׁמַּזִּיק","צָרִיךְ לְהַפְסִיק לֶאֱכֹל מְתוּקִים לְגַמְרֵי, כָּל הַחַיִּים","זֶה מֻתָּר לְגַמְרֵי, כָּל עוֹד יֵשׁ לָהֶם הֶכְשֵׁר"],1,"הַשּׁוֹמֵר עַל בְּרִיאוּתוֹ מְקַיֵּם מִצְוָה. מְמַעֲטִים בַּחֲטִיפִים וּמַרְבִּים בְּפֵרוֹת וִירָקוֹת – אֲבָל בְּלִי הַקְפָּדָה קִיצוֹנִית, כִּי הַשִּׂמְחָה הִיא יְסוֹד הַבְּרִיאוּת.","פֶּרֶק ל״ו, הֲלָכָה א׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["כּוֹס מַיִם נִשְׁאֲרָה גְּלוּיָה כָּל הַלַּיְלָה עַל הַשֻּׁלְחָן. הַאִם מֻתָּר לִשְׁתּוֹת מִמֶּנָּה?",["לֹא, כִּי חֲכָמִים אָסְרוּ מַשְׁקֶה גָּלוּי לְעוֹלָם","כֵּן, כִּי הַיּוֹם אֵין נְחָשִׁים בְּתוֹךְ הַבָּתִּים","רַק אַחֲרֵי שֶׁמַּרְתִּיחִים אֶת הַמַּיִם עַל הָאֵשׁ","רַק אִם מְבָרְכִים עֲלֵיהֶם בְּרָכָה מְיֻחֶדֶת קֹדֶם"],1,"הָאִסּוּר נִקְבַּע כְּשֶׁנְּחָשִׁים הָיוּ מַטִּילִים אֶרֶס בְּמַשְׁקָאוֹת גְּלוּיִים. הַיּוֹם מֻתָּר, וְיֵשׁ שֶׁמְּכַסִּים מַשְׁקָאוֹת מִשּׁוּם כָּבוֹד לְתַקָּנַת חֲכָמִים וּמִשּׁוּם נִקָּיוֹן.","פֶּרֶק ל״ו, הֲלָכָה ב׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["סֻכָּרִיּוֹת גּוּמִי עֲשׂוּיוֹת בְּעִקָּר מִסֻּכָּר. לָמָּה בְּכָל זֹאת הֵן צְרִיכוֹת הֶכְשֵׁר?",["כִּי סֻכָּר שֶׁמְּיֻצָּר בְּחוּץ לָאָרֶץ אָסוּר תָּמִיד לֶאֱכֹל","כִּי גֶ׳לָטִין אוֹ צֶבַע בָּהֶן עֲשׂוּיִים לִפְעָמִים מִדָּבָר אָסוּר","כִּי מַמְתַּקִּים מְתוּקִים מַזִּיקִים לַשִּׁנַּיִם וְלַבְּרִיאוּת","כִּי אָסוּר לֶאֱכֹל שׁוּם דָּבָר שֶׁיֻּצַּר בְּמִפְעָל גָּדוֹל"],1,"גֶ׳לָטִין מֻפָק לְרֹב מִבַּעֲלֵי חַיִּים טְמֵאִים אוֹ שֶׁלֹּא נִשְׁחֲטוּ, וְצֶבַע אָדֹם אֶחָד מֻפָק מִכְּנִימוֹת. הַקּוֹנֶה לֹא יָכוֹל לָדַעַת – וְלָכֵן צָרִיךְ הַשְׁגָּחָה.","פֶּרֶק ל״ז, הֲלָכוֹת א׳, ג׳, ה׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["יוֹסִי רוֹצֶה לִשְׁמֹר שַׂקִּית עוּגִיּוֹת מִתַּחַת לַמִּטָּה שֶׁלּוֹ. מָה נָכוֹן?",["מֻתָּר, כִּי שָׁם אַף אֶחָד בַּבַּיִת לֹא יִקַּח אוֹתָהּ","מֻתָּר, אִם הַשַּׂקִּית סְגוּרָה הֵיטֵב וּנְקִיָּה מִבַּחוּץ","לֹא מַנִּיחִים אֹכֶל תַּחַת הַמִּטָּה, כִּי אֵין זֶה כְּבוֹדוֹ","אָסוּר, וְאִם הִנִּיחַ שָׁם חוֹבָה לִזְרֹק אֶת הָעוּגִיּוֹת"],2,"לְכַתְּחִלָּה לֹא מַנִּיחִים מַאֲכָלִים תַּחַת הַמִּטָּה: הֵם עֲלוּלִים לְהִתְלַכְלֵךְ, לְהִשָּׁכַח וּלְהִתְעַפֵּשׁ, וְאֵין זֶה כְּבוֹדָם. וְאִם הִנִּיחוּ – מֻתָּר לֶאֱכֹל אוֹתָם.","פֶּרֶק ל״ו, הֲלָכָה ח׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["בַּחֲנוּת יֵשׁ מוּצָרִים שֶׁגּוֹיִם בִּשְּׁלוּ אוֹ אָפוּ, וְכֻלָּם מֵחֳמָרִים כְּשֵׁרִים. בְּאֵיזֶה מֵהֶם יֵשׁ אִסּוּר בִּשּׁוּלֵי גּוֹיִם?",["בְּשׁוֹקוֹלָד, כִּי מְמִיסִים וּמְבַשְּׁלִים אוֹתוֹ בַּמִּפְעָל","בְּדִגְנֵי בֹּקֶר, כִּי אוֹכְלִים אוֹתָם לָשׂבַע בַּאֲרוּחַת בֹּקֶר","בְּפִצּוּחִים קְלוּיִים, כִּי קוֹלִים אוֹתָם בְּאֵשׁ חֲזָקָה","בְּקָפֶה, כִּי פּוֹלֵי הַקָּפֶה נִקְלִים וּמִתְבַּשְּׁלִים"],1,"אִסּוּר בִּשּׁוּלֵי גּוֹיִם הוּא רַק בְּמַאֲכָל שֶׁ״עוֹלֶה עַל שֻׁלְחַן מְלָכִים״ – שֶׁאוֹכְלִים אוֹתוֹ בִּסְעוּדָה. בְּמַמְתַּקִּים, שׁוֹקוֹלָד, פִּצּוּחִים וּשְׁאָר חֲטִיפִים – אֵין אִסּוּר. בְּדִגְנֵי בֹּקֶר וּפְרִיכִיּוֹת אֹרֶז – יֵשׁ, כִּי אוֹכְלִים אוֹתָם לָשׂבַע. וּבְקָפֶה – אֵין, כִּי עִקָּרוֹ מַיִם.","פֶּרֶק כ״ח, הֲלָכָה ז׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["קָנוּ צִנְצֶנֶת זְכוּכִית יָפָה מִתּוֹצֶרֶת חוּץ, וְרוֹצִים לָשִׂים בָּהּ סֻכָּרִיּוֹת עֲטוּפוֹת. הַאִם צָרִיךְ לְהַטְבִּיל אוֹתָהּ?",["כֵּן, כִּי כָּל כְּלִי זְכוּכִית שֶׁבָּא מִגּוֹי חַיָּב טְבִילָה","לֹא, כִּי הַסֻּכָּרִיּוֹת עֲטוּפוֹת וְאֵינָן נוֹגְעוֹת בַּצִּנְצֶנֶת","כֵּן, אֲבָל רַק אִם הִיא תַּעֲמֹד עַל שֻׁלְחַן הַשַּׁבָּת","לֹא, כִּי צִנְצֶנֶת שֶׁל מַמְתַּקִּים הִיא כְּמוֹ צַעֲצוּעַ"],1,"כֵּלִים לְאִחְסוּן אֹכֶל בַּמִּטְבָּח, כְּמוֹ צִנְצֶנֶת לְסֻכָּר וּלְקָפֶה – צְרִיכִים טְבִילָה. אֲבָל אִם מַנִּיחִים בָּהֶם מַאֲכָלִים עֲטוּפִים, כְּמוֹ סֻכָּרִיּוֹת עֲטוּפוֹת אוֹ שַׂקִּיּוֹת תֵּה – אֵינָם צְרִיכִים טְבִילָה. הַכְּלָל: כֵּלִים שֶׁבָּאִים בְּמַגָּע יָשִׁיר עִם אֹכֶל רָאוּי לַאֲכִילָה – צְרִיכִים טְבִילָה.","פֶּרֶק ל״א, הֲלָכָה ג׳","שׁוֹמְרִים עַל הָעוֹלָם וְעַל הַגּוּף"],["מָתַי מֻתָּר בְּאֶרֶץ יִשְׂרָאֵל לֶאֱכֹל מִן הַחִטָּה הַחֲדָשָׁה שֶׁל הַשָּׁנָה?",["מִיָּד כְּשֶׁהַשִּׁבֳּלִים מַבְשִׁילוֹת וְנִקְצָרוֹת בַּשָּׂדֶה","אַחֲרֵי שֶׁנִּגְמָר יוֹם ט״ז בְּנִיסָן, יוֹם הָעֹמֶר","רַק אַחֲרֵי חַג הַשָּׁבוּעוֹת, כְּשֶׁמַּבְשִׁילָה הַחִטָּה","רַק כְּשֶׁיִּבָּנֶה הַמִּקְדָּשׁ וְיַקְרִיבוּ שָׁם אֶת הָעֹמֶר"],1,"גַּם בְּלִי מִקְדָּשׁ אִסּוּר \"חָדָשׁ\" קַיָּם, וְהַתְּבוּאָה הַחֲדָשָׁה מֻתֶּרֶת אַחֲרֵי שֶׁנִּגְמָר יוֹם ט״ז בְּנִיסָן – \"עַד עֶצֶם הַיּוֹם הַזֶּה\". קָרְבַּן שְׁתֵּי הַלֶּחֶם בְּשָׁבוּעוֹת הִתִּיר רַק לְהַקְרִיב בַּמִּקְדָּשׁ מִן הַחִטָּה הַחֲדָשָׁה.","פֶּרֶק א׳, הֲלָכוֹת א׳–ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["לָמָּה, לְפִי חֲכָמִים, צִוְּתָה הַתּוֹרָה לְחַכּוֹת שָׁלֹשׁ שָׁנִים לִפְנֵי שֶׁאוֹכְלִים מִפְּרִי הָעֵץ?",["כִּי הַפֵּרוֹת הָרִאשׁוֹנִים מְסֻכָּנִים לַבְּרִיאוּת שֶׁל הָאוֹכְלִים","כְּדֵי שֶׁנַּתְחִיל לֶאֱכֹל בְּהַלֵּל לַה׳, וְנִלְמַד לְהִתְאַפֵּק","כְּדֵי שֶׁהָעֵץ יִתְחַזֵּק, וְיוּכַל לָתֵת פֵּרוֹת גְּדוֹלִים לַשּׁוּק","כְּדֵי שֶׁכָּל הַפֵּרוֹת שֶׁל הַשָּׁנִים הָאֵלֶּה יִנָּתְנוּ לָעֲנִיִּים"],1,"פֵּרוֹת הַשָּׁנִים הָרִאשׁוֹנוֹת מְעַטִּים, וְאֵין רָאוּי לְהַלֵּל בָּהֶם אֶת ה׳. מְחַכִּים לַשָּׁנָה הָרְבִיעִית, וּבַהַמְתָּנָה לוֹמְדִים לְהִתְאַפֵּק – מַה שֶּׁאָדָם הָרִאשׁוֹן לֹא עָשָׂה.","פֶּרֶק ב׳, הֲלָכָה ב׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["הִגִּיעָה הַשָּׁנָה הָרְבִיעִית שֶׁל עֵץ הָרִמּוֹנִים. מָה עוֹשִׂים כְּדֵי לֶאֱכֹל מִפֵּרוֹתָיו בִּזְמַנֵּנוּ?",["פּוֹדִים אֶת הַפֵּרוֹת עַל מַטְבֵּעַ שֶׁל פְּרוּטָה, בִּבְרָכָה","מַפְרִישִׁים מֵהֶם תְּרוּמוֹת וּמַעַשְׂרוֹת, וְאוֹכְלִים אֶת הַשְּׁאָר","אוֹכְלִים כָּרָגִיל, כִּי שְׁנוֹת הָעָרְלָה כְּבָר נִגְמְרוּ","מְחַכִּים עוֹד שָׁנָה, כִּי אֵין הַיּוֹם בֵּית מִקְדָּשׁ"],0,"פֵּרוֹת \"נֶטַע רְבָעִי\" קְדוֹשִׁים, וְאֵין מַפְרִישִׁים מֵהֶם תְּרוּמוֹת וּמַעַשְׂרוֹת. הַיּוֹם, כְּשֶׁאִי אֶפְשָׁר לֶאֱכֹל אוֹתָם בִּירוּשָׁלַיִם, פּוֹדִים אוֹתָם עַל שְׁוֵה פְּרוּטָה בִּבְרָכָה \"עַל פִּדְיוֹן רְבָעִי\", וּמְאַבְּדִים אֶת הַפְּרוּטָה.","פֶּרֶק ב׳, הֲלָכָה י׳; פֶּרֶק ח׳, הֲלָכָה ד׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּעַל פַּרְדֵּס גָּמַר לֶאֱסֹף אֶת הַפֵּרוֹת. מָה מַפְרִישִׁים רִאשׁוֹן, וּמַדּוּעַ?",["מַעֲשֵׂר עָנִי, כִּי צָרִיךְ לִדְאֹג קֹדֶם לָעֲנִיִּים","תְּרוּמָה גְּדוֹלָה לַכֹּהֵן, שֶׁיּוּכַל לַעֲסֹק בַּתּוֹרָה וּלְלַמְּדָהּ","מַעֲשֵׂר רִאשׁוֹן לַלֵּוִי, כִּי הוּא הַגָּדוֹל מִכָּל הַמַּתָּנוֹת","מַעֲשֵׂר שֵׁנִי, כְּדֵי לְהַעֲלוֹתוֹ מִיָּד לִירוּשָׁלַיִם"],1,"קֹדֶם תְּרוּמָה גְּדוֹלָה לַכֹּהֵן, אַחַר כָּךְ מַעֲשֵׂר רִאשׁוֹן לַלֵּוִי, וְרַק אַחֲרָיו מַעֲשֵׂר שֵׁנִי אוֹ עָנִי. הַמַּתָּנוֹת נִתְּנוּ לַכֹּהֲנִים וְלַלְוִיִּם כְּדֵי שֶׁיִּהְיוּ פְּנוּיִים לְלַמֵּד תּוֹרָה.","פֶּרֶק ז׳, הֲלָכוֹת ב׳–ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["מַה מְּיֻחָד בַּשָּׁנָה הַשְּׁלִישִׁית וּבַשָּׁנָה הַשִּׁשִּׁית שֶׁל מַחֲזוֹר הַשְּׁמִטָּה?",["לֹא מַפְרִישִׁים בָּהֶן מַעַשְׂרוֹת, כִּי הַפֵּרוֹת הֶפְקֵר","מַפְרִישִׁים פַּעֲמַיִם מַעֲשֵׂר רִאשׁוֹן, וְנוֹתְנִים הַכֹּל לַלְוִיִּם","בִּמְקוֹם מַעֲשֵׂר שֵׁנִי נוֹתְנִים מַעֲשֵׂר עָנִי לָעֲנִיִּים","מַעֲלִים אֶת כָּל הַפֵּרוֹת לִירוּשָׁלַיִם וְאוֹכְלִים אוֹתָם שָׁם"],2,"בַּשָּׁנִים הָרִאשׁוֹנָה, הַשְּׁנִיָּה, הָרְבִיעִית וְהַחֲמִישִׁית מַפְרִישִׁים מַעֲשֵׂר שֵׁנִי, וּבַשְּׁלִישִׁית וּבַשִּׁשִּׁית – מַעֲשֵׂר עָנִי. בַּשָּׁנָה הַשְּׁבִיעִית הַפֵּרוֹת הֶפְקֵר וּפְטוּרִים.","פֶּרֶק ז׳, הֲלָכוֹת ט׳, י״א–י״ב; פֶּרֶק ח׳, הֲלָכָה ד׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["מָה עָשָׂה חַקְלַאי כְּשֶׁרָאָה אֶת הַתְּאֵנִים הָרִאשׁוֹנוֹת מַתְחִילוֹת לִגְדֹּל בְּשָׂדֵהוּ?",["קָשַׁר עֲלֵיהֶן חוּט וְאָמַר: הֲרֵי אֵלּוּ בִּכּוּרִים","קָטַף אוֹתָן מִיָּד וְנָתַן אוֹתָן לְעָנִי שֶׁעָבַר","הִשְׁאִיר אוֹתָן עַל הָעֵץ עַד הַשָּׁנָה הָרְבִיעִית","אָכַל אוֹתָן בְּעַצְמוֹ, וּבֵרֵךְ עֲלֵיהֶן שֶׁהֶחֱיָנוּ"],0,"בִּכּוּרִים מְבִיאִים מִשִּׁבְעַת הַמִּינִים: מְסַמְּנִים בְּחוּט אֶת הַפֵּרוֹת הָרִאשׁוֹנִים, וּכְשֶׁהֵם מַבְשִׁילִים מַעֲלִים אוֹתָם בְּשִׂמְחָה לַכֹּהֵן בַּמִּקְדָּשׁ.","פֶּרֶק ז׳, הֲלָכָה ט״ו","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בְּטִיּוּל בַּטֶּבַע מָצְאוּ הַיְּלָדִים עֵץ תְּאֵנָה פְּרָאִי, שֶׁאֵינוֹ שַׁיָּךְ לְאִישׁ. צָרִיךְ לְהַפְרִישׁ מִפֵּרוֹתָיו?",["כֵּן, כִּי כָּל פְּרִי בָּאָרֶץ צָרִיךְ תְּרוּמוֹת וּמַעַשְׂרוֹת","לֹא, כִּי פֵּרוֹת הֶפְקֵר פְּטוּרִים מִתְּרוּמוֹת וּמַעַשְׂרוֹת","כֵּן, אֲבָל רַק אִם אוֹכְלִים אוֹתָם בַּבַּיִת","לֹא, אֲבָל צָרִיךְ לְבָרֵךְ עֲלֵיהֶם בְּרָכָה מְיֻחֶדֶת"],1,"פֵּרוֹת שֶׁכָּל אָדָם רַשַּׁאי לִקְטֹף – פְּטוּרִים מִתְּרוּמוֹת וּמַעַשְׂרוֹת, וּמֻתָּר לֶאֱכֹל אוֹתָם בַּשָּׂדֶה אוֹ בַּבַּיִת. מְבָרְכִים עֲלֵיהֶם כָּרָגִיל: \"בּוֹרֵא פְּרִי הָעֵץ\".","פֶּרֶק ח׳, הֲלָכָה ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["דָּוִד בֶּן שְׁמוֹנֶה רוֹצֶה לְהַפְרִישׁ לְבַד תְּרוּמוֹת וּמַעַשְׂרוֹת מִסַּל פֵּרוֹת. מָה הַדִּין?",["מֻתָּר, אִם הוּא קוֹרֵא בְּדִיּוּק אֶת הַנֹּסַח מִן הַסִּדּוּר","מֻתָּר, אֲבָל רַק בְּלִי לוֹמַר אֶת הַבְּרָכָה","יֶלֶד קָטָן אֵינוֹ יָכוֹל לְהַפְרִישׁ, וְהַהַפְרָשָׁה לֹא חָלָה","מֻתָּר, אִם אַחַר כָּךְ גָּדוֹל אוֹכֵל מִן הַפֵּרוֹת"],2,"מִי שֶׁעוֹד אֵינוֹ מֵבִין אֶת הַמִּצְוָה כָּרָאוּי אֵינוֹ יָכוֹל לְקַיְּמָהּ, וְלָכֵן קְטַנִּים שֶׁהִפְרִישׁוּ – לֹא עָשׂוּ כְּלוּם. דָּוִד יָכוֹל לַעֲזֹר לְאַבָּא, וְאַבָּא יַפְרִישׁ.","פֶּרֶק י׳, הֲלָכָה ב׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בְּשַׁבָּת הִתְבָּרֵר שֶׁמִּן הַפֵּרוֹת שֶׁקִּבְּלוּ בְּעֶרֶב שַׁבָּת מִן הַשָּׂדֶה עוֹד לֹא הִפְרִישׁוּ. מָה עוֹשִׂים?",["מַפְרִישִׁים כָּרָגִיל עִם בְּרָכָה, כִּי זוֹ מִצְוָה","אוֹכְלִים בְּלִי לְהַפְרִישׁ, כִּי בְּשַׁבָּת אִי אֶפְשָׁר","לֹא מַפְרִישִׁים בְּשַׁבָּת, וּמְחַכִּים לְמוֹצָאֵי שַׁבָּת","מַפְרִישִׁים בְּלִי בְּרָכָה, וְאוֹכְלִים מִיָּד אֶת הַשְּׁאָר"],2,"בְּשַׁבָּת וּבְיוֹם טוֹב אֵין מַפְרִישִׁים תְּרוּמוֹת, מַעַשְׂרוֹת וְחַלָּה, כִּי זֶה כְּמוֹ לְתַקֵּן אֶת הַפֵּרוֹת. וְטֶבֶל אָסוּר לֶאֱכֹל – לָכֵן מְחַכִּים לְמוֹצָאֵי שַׁבָּת.","פֶּרֶק י׳, הֲלָכָה ד׳; פֶּרֶק י״א, הֲלָכָה י״ג","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּעַל שָׂדֶה רוֹצֶה שֶׁרַק בֶּן דּוֹדוֹ הֶעָנִי יִקַּח אֶת הַפֵּאָה. מַה הַדִּין?",["מֻתָּר, כִּי צְדָקָה לִקְרוֹבִים קוֹדֶמֶת לְכָל צְדָקָה","אָסוּר, כִּי צָרִיךְ לִפְתֹּחַ אֶת הַשָּׂדֶה לְכָל הָעֲנִיִּים","מֻתָּר, אִם הוּא קוֹטֵף בְּעַצְמוֹ וּמֵבִיא לוֹ הַבַּיְתָה","מֻתָּר, בִּתְנַאי שֶׁיַּשְׁאִיר גַּם פֵּאָה גְּדוֹלָה בְּמִיּוּחָד"],1,"מַתְּנוֹת עֲנִיִּים שַׁיָּכוֹת לְכָל הָעֲנִיִּים, וּמִי שֶׁמּוֹנֵעַ מֵעָנִי לְהִכָּנֵס – גּוֹזֵל אֶת חֶלְקוֹ. וְגַם אָסוּר לִקְטֹף בִּשְׁבִיל עָנִי מְסֻיָּם – הָעֲנִיִּים לוֹקְטִים בְּעַצְמָם.","פֶּרֶק ו׳, הֲלָכוֹת ג׳, ז׳–ח׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["מִשְׁפָּחָה רוֹצָה לֶאֱפוֹת עִסָּה גְּדוֹלָה שֶׁחַיֶּבֶת בְּחַלָּה, אֲבָל לְחַלֵּק אוֹתָהּ לִשְׁתַּיִם כְּדֵי שֶׁלֹּא לְהַפְרִישׁ. מָה הַדִּין?",["מֻתָּר, כִּי הַיּוֹם הַכֹּהֲנִים מִמֵּילָא אֵינָם אוֹכְלִים חַלָּה","אָסוּר לְהִשְׁתַּמֵּט מִן הַמִּצְוָה, וּמַפְרִישִׁים חַלָּה כָּרָגִיל","מֻתָּר, בִּתְנַאי שֶׁאוֹפִים אֶת שְׁנֵי הַחֲלָקִים בְּתַנּוּרִים שׁוֹנִים","מֻתָּר, אִם נוֹתְנִים צְדָקָה בִּמְקוֹם הַחַלָּה"],1,"מִי שֶׁאֵינוֹ רוֹצֶה לֶאֱפוֹת הַרְבֵּה – אֵינוֹ חַיָּב. אֲבָל מִי שֶׁמִּתְכַּוֵּן לֶאֱפוֹת עִסָּה שֶׁחַיֶּבֶת בְּחַלָּה – אָסוּר לוֹ לְחַלֵּק אוֹתָהּ כְּדֵי לְהִפָּטֵר, כִּי בַּמִּצְוָה אָנוּ מִתְקַשְּׁרִים לָרַעְיוֹן הַגָּדוֹל שֶׁלָּהּ.","פֶּרֶק י״א, הֲלָכָה ז׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["אִמָּא וְאַבָּא לָשׁוּ יַחַד בָּצֵק גָּדוֹל לְחַלּוֹת שַׁבָּת. מִי זוֹכֶה לְהַפְרִישׁ אֶת הַחַלָּה?",["אַבָּא, כִּי מִצְוַת הַפְרָשַׁת חַלָּה שַׁיֶּכֶת רַק לִגְבָרִים","אִמָּא, כִּי זְכוּתָהּ קוֹדֶמֶת – הִיא אַחְרָאִית עַל עִנְיְנֵי הַבַּיִת","הַיֶּלֶד הַקָּטָן בְּיוֹתֵר, כְּדֵי לְחַנֵּךְ אוֹתוֹ לְמִצְווֹת","מִי שֶׁהִכְנִיס רִאשׁוֹן אֶת הַקֶּמַח וְהַמַּיִם לַקְּעָרָה"],1,"הַמִּצְוָה שַׁיֶּכֶת לִגְבָרִים וּלְנָשִׁים, אֲבָל כְּשֶׁלָּשׁוּ יַחַד – זְכוּת הָאִשָּׁה קוֹדֶמֶת, כִּי הִיא אַחְרָאִית יוֹתֵר עַל עִנְיְנֵי הַבַּיִת. בַּת וּבֵן שֶׁהִגִּיעוּ לְמִצְווֹת רַשָּׁאִים לְהַפְרִישׁ בְּעַצְמָם.","פֶּרֶק י״א, הֲלָכָה ה׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּחַוָּה רוֹכֵב אֵלִיָּהוּ עַל סוּס, וְהוּא רוֹצֶה שֶׁהַכֶּלֶב שֶׁלּוֹ יָרוּץ אִתּוֹ. מָה מֻתָּר?",["לִקְשֹׁר אֶת רְצוּעַת הַכֶּלֶב לָאֻכָּף, כְּדֵי שֶׁיֵּלֵךְ לְיַד הַסּוּס","לְהַחֲזִיק אֶת רְצוּעַת הַכֶּלֶב בַּיָּד, בְּלִי לִקְשֹׁר לַסּוּס","לִרְתֹּם אֶת הַכֶּלֶב וְאֶת הַסּוּס יַחַד לַעֲגָלָה קְטַנָּה","אָסוּר לְהָבִיא כֶּלֶב לְיַד סוּס, כִּי הֵם שְׁנֵי מִינִים"],1,"רַק כְּשֶׁשְּׁנֵי הַמִּינִים קְשׁוּרִים יַחַד יֵשׁ אִסּוּר כִּלְאַיִם. לָכֵן הָרוֹכֵב עַל סוּס רַשַּׁאי לְהַחֲזִיק בְּיָדוֹ חֶבֶל שֶׁקָּשׁוּר לְכֶלֶב. אֲבָל אִם יִקְשֹׁר אֶת הָרְצוּעָה לָאֻכָּף – לִפְעָמִים הַכֶּלֶב יִמְשֹׁךְ אֶת הַסּוּס קָדִימָה, וְהֵם יַעַבְדוּ יַחַד.","פֶּרֶק ג׳, הֲלָכָה ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּמִּרְפֶּסֶת בְּבֵיתוֹ שֶׁבִּירוּשָׁלַיִם רוֹצֶה עֻזִּיאֵל לִשְׁתֹּל עָצִיץ. מָה מֻתָּר לוֹ לִזְרֹעַ בּוֹ יַחַד?",["עַגְבָנִיָּה וּמְלָפְפוֹן, כִּי עָצִיץ קָטָן אֵינוֹ שָׂדֶה","פְּרָחִים מִכַּמָּה סוּגִים, כִּי צִמְחֵי נוֹי אֵינָם אֲסוּרִים","חַסָּה וְגֶזֶר, כִּי שְׁנֵיהֶם יְרָקוֹת שֶׁאוֹכְלִים בְּסָלָט","חִטָּה וַאֲפוּנָה, אִם יֵשׁ לָעָצִיץ נֶקֶב בַּתַּחְתִּית"],1,"גַּם בְּעָצִיץ שֶׁבְּאֶרֶץ יִשְׂרָאֵל אָסוּר לִזְרֹעַ שְׁנֵי מִינִים יַחַד – בְּעָצִיץ נָקוּב מִן הַתּוֹרָה, וּבְעָצִיץ שֶׁאֵינוֹ נָקוּב מִדִּבְרֵי חֲכָמִים. הָאִסּוּר הוּא בִּתְבוּאָה, קִטְנִיּוֹת וִירָקוֹת. אֲבָל צְמָחִים לְנוֹי אוֹ לִרְפוּאָה – אֵינָם בִּכְלַל הָאִסּוּר.","פֶּרֶק ד׳, הֲלָכָה א׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["לִפְנֵי שָׁנָה שָׁתַל רְאוּבֵן שְׁתִיל לִימוֹן בְּעָצִיץ חֶרֶס גָּדוֹל בַּסָּלוֹן, וּכְבָר יֵשׁ עָלָיו לִימוֹן. מָה הַדִּין?",["מֻתָּר לֶאֱכֹל, כִּי עֵץ בְּתוֹךְ הַבַּיִת פָּטוּר מֵעָרְלָה","הַלִּימוֹן עָרְלָה, כִּי עֵץ בְּעָצִיץ חֶרֶס נֶחְשָׁב נָטוּעַ בָּאָרֶץ","מֻתָּר לֶאֱכֹל, כִּי הָעֵץ עוֹד לֹא נִשְׁתַּל בָּאֲדָמָה","הַלִּימוֹן מֻתָּר, אִם מַעֲבִירִים אֶת הָעֵץ עַכְשָׁו לֶחָצֵר"],1,"עֵץ שֶׁגָּדֵל בְּתוֹךְ בַּיִת חַיָּב בְּעָרְלָה, כִּי הָעִקָּר שֶׁהָעֵץ נָטוּעַ בָּאָרֶץ, וְהַגַּג שֶׁמֵּעָלָיו אֵינוֹ פּוֹטֵר. וְעֵץ בְּעָצִיץ חֶרֶס נֶחְשָׁב כְּנָטוּעַ בָּאָרֶץ, כִּי הַשָּׁרָשִׁים יְכוֹלִים לִבְקֹעַ אֶת הַחֶרֶס. לָכֵן פֵּרוֹתָיו בְּשָׁלֹשׁ הַשָּׁנִים הָרִאשׁוֹנוֹת – עָרְלָה.","פֶּרֶק ב׳, הֲלָכָה ז׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּחֲנוּת בְּאֶרֶץ יִשְׂרָאֵל רָאָה נָתָן עוּגִיּוֹת מִחוּץ לָאָרֶץ, עִם הֶכְשֵׁר שֶׁל חוּץ לָאָרֶץ בִּלְבַד. מָה הַדִּין?",["מֻתָּר, כִּי כָּל הֶכְשֵׁר מִכָּל מָקוֹם מַסְפִּיק תָּמִיד","אָסוּר מֵחֲמַת סְפֵק ״חָדָשׁ״, אִם לֹא כָּתוּב שֶׁהַקֶּמַח יָשָׁן","מֻתָּר, כִּי אִסּוּר ״חָדָשׁ״ אֵינוֹ נוֹהֵג בִּזְמַנֵּנוּ כְּלָל","אָסוּר רַק בְּפֶסַח, וּבִשְׁאָר הַשָּׁנָה מֻתָּר לֶאֱכֹל אוֹתָן"],1,"בְּאֶרֶץ יִשְׂרָאֵל מַחְמִירִים בִּסְפֵק ״חָדָשׁ״. כָּל מוּצָר שֶׁיֵּשׁ בּוֹ דָּגָן בְּכַשְׁרוּת שֶׁל חוּץ לָאָרֶץ, בְּלִי אִשּׁוּר שֶׁל הָרַבָּנוּת, וְלֹא צֻיַּן בּוֹ שֶׁהוּא מִתְּבוּאָה יְשָׁנָה – אָסוּר מֵחֲמַת הַסָּפֵק, כִּי רֹב הַכַּשְׁרֻיּוֹת בְּחוּץ לָאָרֶץ מְקִלּוֹת בָּזֶה.","פֶּרֶק א׳, הֲלָכָה ו׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["סָבְתָא מְכִינָה גַ׳חְנוּן בְּסִיר, מִכַּמּוּת גְּדוֹלָה שֶׁל קֶמַח. מָה הַדִּין?",["פָּטוּר מֵחַלָּה, כִּי הוּא נֶאֱפֶה בְּסִיר וְלֹא בְּתַנּוּר","מַפְרִישִׁים חַלָּה בִּבְרָכָה, כִּי מַאֲפֶה בְּסִיר נֶחְשָׁב לֶחֶם","מַפְרִישִׁים בְּלִי בְּרָכָה, כִּי הוּא לֹא לֶחֶם שֶׁל שַׁבָּת","פָּטוּר מֵחַלָּה, כִּי אוֹכְלִים אוֹתוֹ רַק בְּבֹקֶר שַׁבָּת"],1,"מַאֲפֶה הוּא מָה שֶׁנֶּאֱפֶה בְּלִי לִהְיוֹת בְּתוֹךְ נוֹזְלִים – גַּם בְּמַחֲבַת אוֹ בְּסִיר עִם מְעַט שֶׁמֶן. לָכֵן מַפְרִישִׁים חַלָּה בִּבְרָכָה מִמַּלַּוַּאח וּמוּפְלֶטָה שֶׁנֶּאֱפִים בְּמַחֲבַת, וּמִכֻּבָּאנֶה וְגַ׳חְנוּן שֶׁנֶּאֱפִים בְּסִיר – כְּשֶׁיֵּשׁ בָּהֶם שִׁעוּר.","פֶּרֶק י״א, הֲלָכָה י׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["בַּגַּן לָשׁ כָּל יֶלֶד חַלָּה קְטַנָּה, וּמַדְבִּיקִים עָלֶיהָ פֶּתֶק עִם שְׁמוֹ. כָּל הַקֶּמַח יַחַד הוּא כַּמּוּת גְּדוֹלָה. מָה הַדִּין?",["מַפְרִישִׁים חַלָּה אַחַת בִּבְרָכָה עַל כָּל הַחַלּוֹת שֶׁבַּגַּן","אֵין חוֹבַת חַלָּה, כִּי הַבְּצֵקִים שֶׁל הַיְּלָדִים אֵינָם מִצְטָרְפִים","כָּל יֶלֶד מַפְרִישׁ חַלָּה בִּבְרָכָה מִן הַבָּצֵק הַקָּטָן שֶׁלּוֹ","רַק הַגַּנֶּנֶת מַפְרִישָׁה, כִּי הַקֶּמַח וְהַבְּצֵקִים שַׁיָּכִים לָהּ"],1,"בְּצֵקִים שֶׁעוֹמְדִים לְהִתְחַלֵּק, וְכָל אֶחָד מַקְפִּיד לָקַחַת אֶת שֶׁלּוֹ – אֵינָם מִצְטָרְפִים לְשִׁעוּר חַלָּה. לָכֵן גַּנֶּנֶת שֶׁאוֹפָה עִם הַיְּלָדִים, וְכָל יֶלֶד לָשׁ לְעַצְמוֹ וּמַדְבִּיקִים עַל הַבָּצֵק אֶת שְׁמוֹ – הַחַלּוֹת אֵינָן מִצְטָרְפוֹת.","פֶּרֶק י״א, הֲלָכָה ח׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["אַבָּא וְאִמָּא אָמְרוּ פַּעַם שֶׁהֵם שְׂמֵחִים כְּשֶׁשִּׁירָה בַּת הַשְּׁתֵּים עֶשְׂרֵה מַפְרִישָׁה תְּרוּמוֹת וּמַעַשְׂרוֹת. עַכְשָׁו הֵם לֹא בַּבַּיִת. מָה הַדִּין?",["אָסוּר לָהּ, כִּי רַק בַּעַל הַפֵּרוֹת עַצְמוֹ יָכוֹל לְהַפְרִישׁ","מֻתֶּרֶת לְהַפְרִישׁ, וּלְכַתְּחִלָּה עָדִיף לְבַקֵּשׁ רְשׁוּת מְפֹרֶשֶׁת","מֻתֶּרֶת, גַּם אִם הִיא אֵינָהּ מְבִינָה אֶת מִלּוֹת הַנֹּסַח","מֻתֶּרֶת רַק אִם אַבָּא חוֹתֵם לָהּ עַל שְׁטַר שְׁלִיחוּת"],1,"מִי שֶׁגִּלָּה אֶת דַּעְתּוֹ שֶׁהוּא מְרֻצֶּה שֶׁבְּנוֹ אוֹ בִּתּוֹ יַפְרִישׁוּ מִפֵּרוֹתָיו – רַשָּׁאִים לְהַפְרִישׁ בִּשְׁבִילוֹ גַּם בְּלִי רְשׁוּת מְפֹרֶשֶׁת, וּלְכַתְּחִלָּה עָדִיף לְבַקֵּשׁ. וּמִי שֶׁמַּפְרִישׁ צָרִיךְ לְהָבִין אֶת הַנֹּסַח – בְּלִי הֲבָנָה לֹא יָצָא.","פֶּרֶק י׳, הֲלָכָה ג׳","מִצְווֹת הָאָרֶץ הַטּוֹבָה"],["לָמָּה הֶחְמִירוּ חֲכָמִים בְּיַיִן יוֹתֵר מִבִּשְׁאָר מַאַכְלֵי גּוֹיִם?",["כִּי יַיִן יָקָר יוֹתֵר מִכָּל שְׁאָר הַמַּאֲכָלִים","כִּי הַיַּיִן מְשַׂמֵּחַ וּמְקָרֵב לְבָבוֹת, וְכֹחוֹ גָּדוֹל","כִּי בְּיַיִן קַל מְאוֹד לְעָרֵב מַאֲכָלִים לֹא כְּשֵׁרִים","כִּי הַיַּיִן מִתְקַלְקֵל מַהֵר כְּשֶׁנּוֹגְעִים בּוֹ בַּיָּדַיִם"],1,"כֹּחַ הַיַּיִן גָּדוֹל: הוּא מְשַׂמֵּחַ וּמְקָרֵב לְבָבוֹת. לָכֵן הוּא מַתְאִים לְשִׂמְחָה שֶׁל מִצְוָה – וּמִשּׁוּם כָּךְ גַּם הֶחְמִירוּ בּוֹ, כְּדֵי שֶׁלֹּא יְקָרֵב אוֹתָנוּ לְהִתְבּוֹלְלוּת.","פֶּרֶק כ״ט, הֲלָכָה א׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["פּוֹעֵל גּוֹי חִילוֹנִי, שֶׁאֵינוֹ עוֹבֵד עֲבוֹדָה זָרָה, נָגַע בְּיַיִן שֶׁל יְהוּדִי. מָה דִּין הַיַּיִן?",["אָסוּר בִּשְׁתִיָּה, אֲבָל מֻתָּר לְמָכְרוֹ אוֹ לֵהָנוֹת מִמֶּנּוּ","מֻתָּר לִשְׁתּוֹתוֹ, כִּי הוּא לֹא עוֹבֵד עֲבוֹדָה זָרָה","אָסוּר גַּם בִּשְׁתִיָּה וְגַם בַּהֲנָאָה, וְזוֹרְקִים אוֹתוֹ","מֻתָּר, אִם יְבַשְּׁלוּ אוֹתוֹ אַחֲרֵי שֶׁהוּא נָגַע"],0,"דִּין גּוֹי שֶׁאֵינוֹ עוֹבֵד עֲבוֹדָה זָרָה קַל בְּדַרְגָּה אַחַת: הַיַּיִן אָסוּר בִּשְׁתִיָּה וּמֻתָּר בַּהֲנָאָה. וּבִשּׁוּל אַחֲרֵי הַנְּגִיעָה לֹא מַצִּיל אוֹתוֹ.","פֶּרֶק כ״ט, הֲלָכוֹת ב׳–ג׳, ה׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["לָמָּה יַיִן מְבֻשָּׁל אֵינוֹ נֶאֱסָר כְּשֶׁגּוֹי נוֹגֵעַ בּוֹ?",["כִּי הָאֵשׁ מְטַהֶרֶת אֶת כָּל מָה שֶׁנָּגַע בּוֹ","כִּי בְּיַיִן מְבֻשָּׁל אֵין טַעַם שֶׁל יַיִן בִּכְלָל","כִּי אֶת הַיַּיִן הַמְבֻשָּׁל שׁוֹתִים רַק בַּחַגִּים","כִּי עוֹבְדֵי אֱלִילִים לֹא נִסְּכוּ יַיִן מְבֻשָּׁל"],3,"הַגְּזֵרָה נִקְבְּעָה עַל יַיִן שֶׁרָאוּי לְנִסּוּךְ. יַיִן מְבֻשָּׁל לֹא נִסְּכוּ לָאֱלִילִים, וְלָכֵן מַגַּע גּוֹי אֵינוֹ אוֹסֵר אוֹתוֹ.","פֶּרֶק כ״ט, הֲלָכָה ה׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["פּוֹעֵל גּוֹי הֵרִים בַּקְבּוּק יַיִן סָגוּר בִּפְקָק וְנִעֵר אוֹתוֹ. מָה דִּין הַיַּיִן?",["הַיַּיִן אָסוּר, כִּי הַגּוֹי שִׁכְשֵׁךְ אוֹתוֹ בְּחָזְקָה","הַיַּיִן מֻתָּר, כִּי אֵין נִסּוּךְ בִּכְלִי סָגוּר","הַיַּיִן מֻתָּר רַק אִם הוּא חָתוּם בִּשְׁנֵי חוֹתָמוֹת","הַיַּיִן אָסוּר בִּשְׁתִיָּה, אֲבָל מֻתָּר לְבַשֵּׁל בּוֹ"],1,"כְּשֶׁהַכְּלִי סָגוּר – אֲפִלּוּ בִּפְקָק אֲרָעִי אוֹ בְּשַׂקִּית – הַיַּיִן אֵינוֹ נֶאֱסָר כְּלָל, כִּי אֵין דֶּרֶךְ לְנַסֵּךְ בִּכְלִי סָגוּר.","פֶּרֶק כ״ט, הֲלָכָה ז׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["הַמִּשְׁפָּחָה יוֹצֵאת לְכַמָּה שָׁעוֹת, וְהַפּוֹעֵל הַגּוֹי נִשְׁאָר לְבַד בַּבַּיִת. מָה יַעֲשׂוּ בְּבַקְבּוּק הַיַּיִן הַפָּתוּחַ?",["יַשְׁאִירוּ אוֹתוֹ בַּמְּקָרֵר, כִּי הַפּוֹעֵל לֹא יִגַּע בּוֹ","יְבַקְּשׁוּ מֵהַפּוֹעֵל לְהַבְטִיחַ שֶׁלֹּא יִשְׁתֶּה מִמֶּנּוּ","יִנְעֲלוּ אוֹתוֹ בָּאָרוֹן, אוֹ יַחְתְּמוּ אוֹתוֹ כַּדִּין","יִשְׁפְּכוּ אוֹתוֹ, כִּי אֵין שׁוּם דֶּרֶךְ לִשְׁמֹר עָלָיו"],2,"כְּשֶׁהַגּוֹי יוֹדֵעַ שֶׁאִישׁ לֹא יִרְאֶה אוֹתוֹ, וְאוּלַי יִשְׁתֶּה – הַיַּיִן נֶאֱסָר. לָכֵן חוֹתְמִים אֶת הַבַּקְבּוּק כַּדִּין, אוֹ נוֹעֲלִים אוֹתוֹ בְּאָרוֹן שֶׁאִי אֶפְשָׁר לִפְתֹּחַ.","פֶּרֶק כ״ט, הֲלָכָה ט׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["בְּאוּלָם שִׂמְחוֹת הַמֶּלְצַר אֵינוֹ יְהוּדִי. מָה הַמִּנְהָג?",["הַסּוֹעֲדִים עַצְמָם פּוֹתְחִים אֶת הַבַּקְבּוּק, וְכָל אֶחָד מוֹזֵג לְעַצְמוֹ","הַמֶּלְצַר מוֹזֵג לְכֻלָּם, כִּי הוּא לֹא עוֹבֵד עֲבוֹדָה זָרָה","לֹא שׁוֹתִים יַיִן כְּלָל בְּשִׂמְחָה שֶׁיֵּשׁ בָּהּ מֶלְצָרִים","הַמֶּלְצַר מוֹזֵג, וְאַחַר כָּךְ שׁוֹפְכִים אֶת מָה שֶׁנִּשְׁאַר"],0,"קָשֶׁה לְפַקֵּחַ שֶׁהַמֶּלְצַר לֹא יִגַּע בַּיַּיִן, וְלָכֵן נוֹהֲגִים שֶׁהַסּוֹעֲדִים מוֹזְגִים לְעַצְמָם. וּבְדִיעֲבַד, אִם הוּא מָזַג – הַיַּיִן כָּשֵׁר.","פֶּרֶק כ״ט, הֲלָכָה ח׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["גּוֹי כּוֹעֵס נָגַע בְּיַיִן שֶׁל יְהוּדִי, רַק כְּדֵי לְהַכְעִיס וּלְהַפְסִיד לוֹ אֶת הַיַּיִן. מָה הַדִּין?",["הַיַּיִן אָסוּר, כִּי כָּל נְגִיעָה שֶׁל גּוֹי אוֹסֶרֶת","הַיַּיִן מֻתָּר רַק לְבִשּׁוּל, וְלֹא לִשְׁתִיָּה","צָרִיךְ לְהַעֲנִישׁ אֶת הַגּוֹי, וְאָז הַיַּיִן מֻתָּר","הַיַּיִן מֻתָּר, וּכְדַאי לִשְׁתּוֹת מִמֶּנּוּ לְפָנָיו"],3,"עַל נְגִיעָה כְּדֵי לְהַכְעִיס לֹא גָּזְרוּ חֲכָמִים. וְאַדְּרַבָּה – שׁוֹתִים מִן הַיַּיִן לִפְנֵי הַגּוֹי, כְּדֵי שֶׁיֵּדַע שֶׁלֹּא הִצְלִיחַ לִפְסֹל אוֹתוֹ.","פֶּרֶק כ״ט, הֲלָכָה י׳","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["מְעַט חָלָב נָפַל לְסִיר גָּדוֹל שֶׁל מְרַק בָּשָׂר. מָתַי הַמָּרָק כָּשֵׁר?",["תָּמִיד, כִּי זֶה קָרָה בְּטָעוּת וּבְלִי כַּוָּנָה","אִם מוֹסִיפִים מִיָּד מַיִם עַד שֶׁיִּהְיֶה פִּי שִׁשִּׁים","אִם יֵשׁ בַּסִּיר פִּי שִׁשִּׁים מִן הֶחָלָב","אִם הֶחָלָב שֶׁנָּפַל הָיָה פָּחוֹת מִכּוֹס אַחַת"],2,"כְּשֶׁיֵּשׁ פִּי שִׁשִּׁים – טַעַם הֶחָלָב אֵינוֹ מֻרְגָּשׁ, וְכָל מָה שֶׁבַּסִּיר מִצְטָרֵף. אֲבָל אָסוּר לְהוֹסִיף מַיִם כְּדֵי לְבַטֵּל.","פֶּרֶק ל״ד, הֲלָכוֹת ג׳, י״ג","עַם מְיֻחָד גַּם בַּמִּטְבָּח"],["מִשְׁפָּחָה הִגִּיעָה לְצִימֶר וְשָׁכְחָה לְהָבִיא כֵּלִים כְּשֵׁרִים. מָה מֻתָּר לָהֶם לַעֲשׂוֹת בִּשְׁעַת הַדְּחָק?",["לְבַשֵּׁל פַּסְטָה בַּסִּיר שֶׁל הַצִּימֶר, אִם שׁוֹטְפִים אוֹתוֹ הֵיטֵב","לֶאֱכֹל דִּגְנֵי בֹּקֶר עִם חָלָב קַר בִּקְעָרָה נְקִיָּה שֶׁל הַצִּימֶר","לִצְלוֹת בָּשָׂר עַל הַמַּנְגָּל שֶׁל הַצִּימֶר, בְּלִי לְהַכְשִׁיר אֶת הָרֶשֶׁת","לְחַמֵּם מָרָק בַּקְּעָרוֹת הַנְּקִיּוֹת שֶׁל הַצִּימֶר בְּתוֹךְ הַמִּיקְרוֹגַל"],1,"בִּשְׁעַת הַדְּחָק מֻתָּר לְהִשְׁתַּמֵּשׁ בְּכֵלִים נְקִיִּים שֶׁל טְרֵפָה לְמַאֲכָלִים קָרִים – כְּמוֹ קְעָרוֹת לְחָלָב עִם דְּגָנִים, צַלָּחוֹת לְסָלָט וְכוֹסוֹת לִשְׁתִיָּה קָרָה. אֲבָל לְמַאֲכָל חַם – אָסוּר, וְאֶת רֶשֶׁת הַמַּנְגָּל חַיָּבִים לְהַכְשִׁיר בָּאֵשׁ.","פֶּרֶק ל״ג, הֲלָכָה י״א","עַם מְיֻחָד גַּם בַּמִּטְבָּח"]]};